function redactToolArguments(
  _toolName: string,
  args: Record<string, unknown>,
): unknown {
  const textFields = new Set([
    "text",
    "content",
    "summary",
    "templateText",
    "code",
    "html",
    "svg",
  ]);
  const output: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(args)) {
    if (typeof value === "string" && textFields.has(key)) {
      output[key] = truncateForTrace(value, 600);
    } else {
      output[key] = value;
    }
  }

  return output;
}

function truncateTracePayload(payload: unknown): unknown {
  if (typeof payload === "string") {
    return truncateForTrace(payload, 1000);
  }

  if (Array.isArray(payload)) {
    return payload.slice(0, 20).map((item) => truncateTracePayload(item));
  }

  if (!isRecord(payload)) {
    return payload;
  }

  const output: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(payload)) {
    if (typeof value === "string") {
      output[key] = truncateForTrace(value, 1000);
    } else if (Array.isArray(value)) {
      output[key] = value
        .slice(0, 20)
        .map((item) => truncateTracePayload(item));
    } else if (isRecord(value)) {
      output[key] = truncateTracePayload(value);
    } else {
      output[key] = value;
    }
  }

  return output;
}

function truncateForTrace(text: string, maxChars: number): string {
  return text.length <= maxChars ? text : `${text.slice(0, maxChars)}\n[truncated]`;
}

function truncateForPromptAnchor(text: string, maxChars = 2000): string {
  return text.length <= maxChars
    ? text
    : `${text.slice(0, maxChars)}\n[truncated]`;
}

function appendRelevancePromptContext(
  basePrompt: string,
  label: string,
  context: unknown,
): string {
  const serialized =
    typeof context === "string" ? context : (JSON.stringify(context) ?? "");
  const trimmed = serialized.trim();
  if (!trimmed) {
    return basePrompt;
  }

  return [basePrompt, `${label}: ${truncateForPromptAnchor(trimmed)}`]
    .filter((part) => part.trim().length > 0)
    .join("\n\n");
}

function getNumber(value: unknown): number | undefined {
  return typeof value === "number" ? value : undefined;
}

function emitDirectAssistantAnswer(
  content: string,
  events: AgentRunEvents,
  requiresEnglishGuard = false,
) {
  const sanitized = sanitizeAssistantContent(content);
  if (!sanitized.trim()) {
    return;
  }
  if (requiresEnglishGuard) {
    assertEnglishOnlyVisibleOutput(sanitized, events);
  }

  emitStatus(events, "Drafting final answer...", "final_answer");
  events.onFinalStart?.();
  events.onAssistantMessageStart?.();
  events.onFinalDelta?.(sanitized);
  events.onAssistantDelta?.(sanitized);
  events.onFinalDone?.();
  events.onAssistantMessageDone?.();
}

function assertEnglishOnlyVisibleOutput(
  content: string,
  events: AgentRunEvents,
): void {
  const language = inspectEnglishOnlyOutput(content);
  if (language.ok) {
    return;
  }

  events.onStreamLifecycle?.({
    kind: "buffering_language",
    elapsedMs: 0,
    bufferedChars: content.length,
    message: "Language gate retrying English-only output...",
  });
  events.onStatus?.("Blocked non-English output before showing it.");
  throw new ModelClientError(
    "invalid_response",
    "Model produced non-English output.",
    {
      details: language,
    },
  );
}

function isEnglishOnlyGuardError(error: unknown): boolean {
  return (
    error instanceof ModelClientError &&
    error.category === "invalid_response" &&
    /non-English output|English-only guard/i.test(error.message)
  );
}

/**
 * The exact absolute directory a known-folder export wrote, if this run made
 * one. A user who asked for a deliverable "on my desktop" needs the path, and
 * the receipt is the only place it is proven.
 */
export function deliveredHostDirectoryPathV1(
  receipts: readonly AgentRunReceipt[],
): string | null {
  for (let index = receipts.length - 1; index >= 0; index -= 1) {
    const receipt = receipts[index]!;
    if (receipt.toolName !== "code_workspace_export_directory") continue;
    const candidate =
      typeof receipt.resource?.path === "string" && receipt.resource.path
        ? receipt.resource.path
        : typeof receipt.path === "string" && receipt.path
          ? receipt.path
          : null;
    if (candidate) return candidate;
  }
  return null;
}

function emitLocalWriteSummary(
  events: AgentRunEvents,
  receipts: AgentRunReceipt[],
) {
  // "Done. 6 write operations completed." told a user who asked for a game on
  // their desktop nothing about where it landed. Name the verified path.
  const deliveredPath = deliveredHostDirectoryPathV1(receipts);
  const message = deliveredPath
    ? `Done. Delivered to ${deliveredPath}.`
    : receipts.length === 1
      ? `Done. ${receipts[0].message}.`
      : receipts.length > 1
        ? `Done. ${receipts.length} write operations completed.`
        : "Done. Write operation completed.";

  emitDirectAssistantAnswer(message, events);
}

async function streamCurrentNoteWriteback({
  kind,
  preparedSectionEdit,
  modelClient,
  messages,
  events,
  toolContext,
  knownToolNames,
  relevancePrompt,
  think,
  options,
  abortSignal,
  onThinkingUnsupported,
  onPartialReceipt,
  stagedContent,
  missionPrompt,
  lazyCreatePath,
  onNoteCreated,
}: {
  kind: StreamingWritebackKind;
  preparedSectionEdit: PreparedStreamingSectionEdit | null;
  modelClient: ModelClient;
  messages: ModelChatMessage[];
  events: AgentRunEvents;
  toolContext: ToolExecutionContext;
  knownToolNames: Set<string>;
  relevancePrompt?: string;
  think?: ModelThink;
  options?: ModelRequestOptions;
  abortSignal?: AbortSignal;
  onThinkingUnsupported: () => void;
  onPartialReceipt?: (receipt: AgentRunReceipt) => void;
  /** Exact sanitized content that has already passed proof verification. */
  stagedContent?: string;
  missionPrompt?: string;
  lazyCreatePath?: string | null;
  onNoteCreated?: (file: { path: string; basename: string }) => void;
}): Promise<AgentRunReceipt> {
  let originalNoteContentForSafety = "";
  try {
    const safetyFile =
      toolContext.getCurrentMarkdownFile?.() ??
      toolContext.app.workspace.getActiveFile();
    if (safetyFile && "extension" in safetyFile && safetyFile.extension === "md") {
      originalNoteContentForSafety =
        toolContext.getCurrentMarkdownContent?.(safetyFile as never) ??
        (await toolContext.app.vault.read(safetyFile as never));
    }
  } catch {
    originalNoteContentForSafety = "";
  }
  const writer = await createStreamingNoteWriter({
    kind,
    toolContext,
    preparedSectionEdit,
    lazyCreatePath,
    onNoteCreated,
  });
  const activeBasename =
    toolContext.getCurrentMarkdownFile?.()?.basename ??
    toolContext.app.workspace.getActiveFile()?.basename ??
    (lazyCreatePath
      ? lazyCreatePath.replace(/^.*\//, "").replace(/\.md$/i, "")
      : undefined);
  const resolvedMissionPrompt = missionPrompt ?? toolContext.originalPrompt;
  const expandExistingDraft =
    kind === "replace" &&
    typeof resolvedMissionPrompt === "string" &&
    hasWordCountShortfallFollowUp(resolvedMissionPrompt);
  const includeCurrentDraftContext =
    kind === "replace" &&
    typeof resolvedMissionPrompt === "string" &&
    (expandExistingDraft ||
      prefersStreamedReplaceForEditOrganize(resolvedMissionPrompt));
  let expandDraftContext: string | null = null;
  if (includeCurrentDraftContext) {
    try {
      const file =
        toolContext.getCurrentMarkdownFile?.() ??
        toolContext.app.workspace.getActiveFile();
      if (file && "extension" in file && file.extension === "md") {
        const draft =
          originalNoteContentForSafety ||
          toolContext.getCurrentMarkdownContent?.(file as never) ||
          (await toolContext.app.vault.read(file as never));
        if (typeof draft === "string" && draft.trim()) {
          expandDraftContext = [
            expandExistingDraft
              ? "CURRENT DRAFT to expand in place (under word target). Edit and add detail into this existing corpus until the soft ±5% band around the target; return one complete expanded note body — not a from-scratch rewrite and not an append:"
              : "CURRENT NOTE to revise in place. Return the full replacement markdown for the current note:",
            truncateForPromptAnchor(draft, MAX_EDIT_CURRENT_NOTE_CHARS),
          ].join("\n\n");
        }
      }
    } catch {
      expandDraftContext = null;
    }
  }
  const writebackPromptOptions = {
    missionPrompt: resolvedMissionPrompt,
    activeBasename,
    expandExistingDraft,
  };
  const writebackMessages = expandDraftContext
    ? [
        ...messages,
        {
          role: "system" as const,
          content: expandDraftContext,
        },
      ]
    : messages;

  emitStatus(events, "Streaming writeback to note...", "final_answer");
  events.onFinalStart?.();
  events.onAssistantMessageStart?.();

  let response: ModelChatResponse | null = null;
  let emittedContent = "";

  const streamAttempt = async (
    retry: boolean,
  ): Promise<{
    response: ModelChatResponse;
    toolRequestDetected: boolean;
    content: string;
    wroteContent: boolean;
    allowRetry: boolean;
  }> => {
    const instruction = buildStreamingWritebackPrompt(
      kind,
      preparedSectionEdit,
      retry,
      writebackPromptOptions,
    );
    const streamRequest: ModelChatRequest = {
      messages: [
        ...writebackMessages,
        {
          // A late system-only handoff is unreliable for agentic providers such
          // as Kimi after the main mission prompt/tool transcript: the provider
          // can stop after a tiny thinking-only response even with `think:false`.
          // Make the concrete content-generation handoff a user turn so the
          // provider emits the requested Markdown while the plugin still owns
          // validation, streaming, and the vault mutation.
          role: "user" as const,
          content: instruction,
        },
      ],
      // Content-only finalization: never omit think (Ollama may default ON).
      // Prefer host writeback policy (off / gpt-oss low) over agent-step think.
      think: resolveWritebackThink(toolContext.settings),
      options,
      abortSignal,
    };
    const metricName = retry ? "stream_writeback_retry" : "stream_writeback";
    const requestChars = measureSerializedChars(streamRequest);
    const startedAt = nowMs();
    const lifecycle = createStreamLifecycleTracker(events, startedAt);
    const contentSanitizer = createAssistantContentSanitizer();
    const thinkingStream = createThinkingStream(events);
    const liveEmitter = createLiveWritebackEmitter({
      events,
      writer,
      knownToolNames,
      relevancePrompt,
      lifecycle,
    });
    let attemptContent = "";

    lifecycle.mark("stream_started", "Waiting for provider to send content...");
    emitModelCallTrace(events, {
      id: retry
        ? "model-call-stream-writeback-retry"
        : "model-call-stream-writeback",
      message: `Model stream: ${metricName}`,
      request: streamRequest,
    });

    try {
      const attemptResponse = await streamChatWithThinkingFallback({
        modelClient,
        request: streamRequest,
        events,
        streamEvents: {
          onRawChunk: () => {
            lifecycle.mark("stream_connected", "Connected to model stream.");
            lifecycle.mark(
              "first_raw_chunk",
              "Provider sent the first stream chunk.",
            );
          },
          onContentDelta: (delta) => {
            lifecycle.mark(
              "first_content_delta",
              "Received answer text; checking early output...",
            );
            const sanitized = contentSanitizer.push(delta);
            if (!sanitized) {
              return;
            }

            attemptContent += sanitized;
            liveEmitter.push(sanitized);
          },
          onThinkingDelta: (delta) => {
            lifecycle.mark(
              "first_thinking_delta",
              "Received thinking, waiting for answer text...",
            );
            thinkingStream.onDelta(delta);
          },
        },
        onThinkingUnsupported,
        // After any note bytes are flushed, a transport retry would re-stream
        // from token 0 into the same writer and duplicate the partial essay.
        shouldRetry: () => !liveEmitter.getWriteSession().released,
      });
      emitMetricEvent(events, {
        kind: "model_stream",
        name: metricName,
        durationMs: elapsedMs(startedAt),
        requestChars,
        responseChars: measureSerializedChars(attemptResponse.message),
        ...extractTokenUsageFields(attemptResponse.raw),
      });

      const trailingContent = contentSanitizer.flush();
      if (trailingContent) {
        attemptContent += trailingContent;
        liveEmitter.push(trailingContent);
      }

      thinkingStream.done();

      const sanitizedResponse = sanitizeAssistantContent(
        attemptResponse.message.content,
      );
      if (!attemptContent.trim() && sanitizedResponse.trim()) {
        attemptContent += sanitizedResponse;
        liveEmitter.push(sanitizedResponse);
      }

      const liveState = liveEmitter.finish();
      if (
        liveState.toolRequestDetected ||
        (!liveState.wroteContent &&
          containsRecoverableToolRequest(attemptContent, knownToolNames))
      ) {
        return {
          response: attemptResponse,
          toolRequestDetected: true,
          content: "",
          wroteContent: liveState.wroteContent,
          allowRetry: liveState.retryPolicy.allowRetry,
        };
      }

      return {
        response: attemptResponse,
        toolRequestDetected: false,
        content: attemptContent,
        wroteContent: liveState.wroteContent,
        allowRetry: liveState.retryPolicy.allowRetry,
      };
    } catch (error) {
      emitMetricEvent(events, {
        kind: "model_stream",
        name: metricName,
        durationMs: elapsedMs(startedAt),
        requestChars,
      });
      if (isInvalidResponseError(error)) {
        thinkingStream.done();
        throw error;
      }
      const trailingContent = contentSanitizer.flush();
      if (trailingContent) {
        attemptContent += trailingContent;
        liveEmitter.push(trailingContent);
      }

      thinkingStream.done();
      const liveState = liveEmitter.finish();
      if (liveState.wroteContent) {
        emittedContent += attemptContent;
      }
      // Partial note apply: do not let outer retry re-stream from byte 0.
      if (!liveState.retryPolicy.allowRetry) {
        const detail =
          error instanceof Error ? error.message : String(error);
        throw new Error(
          `Streamed writeback cannot safely retry after partial note apply (${liveState.retryPolicy.reason}). Underlying error: ${detail}`,
        );
      }
      throw error;
    }
  };

  try {
    if (stagedContent !== undefined) {
      if (!stagedContent.trim()) {
        throw new Error(EMPTY_STREAMING_WRITEBACK_MESSAGE);
      }
      assertSafeCurrentNoteWritePayload({
        kind,
        text: stagedContent,
        currentContent:
          kind === "replace" ? originalNoteContentForSafety : undefined,
        allowDestructiveShortReplace:
          typeof resolvedMissionPrompt === "string" &&
          /\b(clear|delete|remove|empty|reset|start\s+fresh)\b/i.test(
            resolvedMissionPrompt,
          ),
      });
      emitStatus(events, "Committing verified writeback to note...", "final_answer");
      // No unverified draft was released, so the verified candidate is the
      // first visible content and should be emitted once as a normal delta.
      events.onFinalDelta?.(stagedContent);
      events.onAssistantDelta?.(stagedContent);
      writer.replaceContent(stagedContent);
      await writer.finish({ force: true });
      events.onFinalDone?.();
      events.onAssistantMessageDone?.();
      events.onStatus?.("Verified writeback complete.");
      return await writer.buildReceipt(false);
    }

    let retryUsed = false;
    let attempt: Awaited<ReturnType<typeof streamAttempt>>;
    try {
      attempt = await streamAttempt(false);
    } catch (error) {
      if (!isEnglishOnlyGuardError(error) || writer.hasWritableContent()) {
        throw error;
      }

      events.onStatus?.(
        "Model produced non-English output; retrying English-only writeback...",
      );
      writer.discardNonWritableContent();
      retryUsed = true;
      attempt = await streamAttempt(true);
    }
    response = attempt.response;

    if (attempt.toolRequestDetected) {
      if (attempt.wroteContent || attempt.allowRetry === false) {
        throw new Error(
          "The model requested a tool after streamed writeback had started. Partial content may have been written.",
        );
      }
      events.onStatus?.(
        "Model requested a tool during writeback; retrying content-only output...",
      );
      writer.discardNonWritableContent();
      retryUsed = true;
      attempt = await streamAttempt(true);
      response = attempt.response;
    } else if (!attempt.content.trim()) {
      events.onStatus?.(
        "No writable content received; retrying content-only writeback...",
      );
      writer.discardNonWritableContent();
      retryUsed = true;
      attempt = await streamAttempt(true);
      response = attempt.response;
    }

    if (attempt.toolRequestDetected) {
      throw new Error(
        "The model requested a tool during streamed writeback instead of returning writable content. Nothing was written.",
      );
    }

    if (!attempt.content.trim()) {
      events.onStatus?.(EMPTY_STREAMING_WRITEBACK_MESSAGE);
      throw new Error(EMPTY_STREAMING_WRITEBACK_MESSAGE);
    }

    if (!retryUsed && hasUnclosedFence(attempt.content)) {
      events.onStatus?.(
        "Streamed writeback ended inside a fenced code block; retrying complete content...",
      );
      // Keep the prior draft on disk until the retry emits bytes. Flushing an
      // empty replace wiped essays when the retry failed or truncated.
      const previousWritable = attempt.content;
      writer.softResetStreamedDraft();
      retryUsed = true;
      attempt = await streamAttempt(true);
      response = attempt.response;

      if (attempt.toolRequestDetected) {
        writer.replaceContent(previousWritable);
        await writer.finish({ force: true });
        throw new Error(
          "The model requested a tool during streamed writeback instead of returning writable content. Prior draft was restored.",
        );
      }

      if (!attempt.content.trim()) {
        writer.replaceContent(previousWritable);
        await writer.finish({ force: true });
        events.onStatus?.(EMPTY_STREAMING_WRITEBACK_MESSAGE);
        throw new Error(EMPTY_STREAMING_WRITEBACK_MESSAGE);
      }
    }

    const wordTarget = parseWritebackWordCountTargetFromMessages(messages);
    let correctionUsed = false;
    let contentToWrite = attempt.content;
    if (wordTarget) {
      const initialCount = countMarkdownVisibleText(contentToWrite).wordCount;
      if (shouldRequestWordCountCorrection(initialCount, wordTarget)) {
        events.onStatus?.(
          `Word count ${initialCount}/${wordTarget.target} outside target; requesting one correction pass...`,
        );
        const corrected = await requestWordCountCorrection({
          modelClient,
          messages,
          draft: contentToWrite,
          wordTarget,
          currentCount: initialCount,
          events,
          think,
          options,
          abortSignal,
          onThinkingUnsupported,
          metricName: "stream_writeback_word_count_correction",
        });
        if (corrected.trim()) {
          contentToWrite = corrected;
          writer.replaceContent(corrected);
          events.onFinalReplace?.(corrected);
          events.onAssistantReplace?.(corrected);
          correctionUsed = true;
        }
      }
    }

    emittedContent = contentToWrite;

    assertSafeCurrentNoteWritePayload({
      kind,
      text: contentToWrite,
      currentContent:
        kind === "replace" ? originalNoteContentForSafety : undefined,
      allowDestructiveShortReplace:
        typeof resolvedMissionPrompt === "string" &&
        /\b(clear|delete|remove|empty|reset|start\s+fresh)\b/i.test(
          resolvedMissionPrompt,
        ),
    });

    await writer.finish({ force: true });

    events.onFinalDone?.();
    events.onAssistantMessageDone?.();
    if (response) {
      messages.push(withoutThinking(response.message));
    }
    if (wordTarget) {
      const count = countMarkdownVisibleText(contentToWrite).wordCount;
      events.onStatus?.(
        `Word count: ${count}/${wordTarget.target} (${
          shouldRequestWordCountCorrection(count, wordTarget)
            ? "outside target"
            : "within target"
        }; correction=${correctionUsed ? "used" : "not used"}).`,
      );
    }
    events.onStatus?.("Streaming writeback complete.");
    return await writer.buildReceipt(false);
  } catch (error) {
    await writer.finish();
    events.onFinalDone?.();
    events.onAssistantMessageDone?.();

    if (writer.hasWritableContent()) {
      const receipt = await writer.buildReceipt(true);
      onPartialReceipt?.(receipt);
      events.onReceipt?.(receipt);
      events.onStatus?.(
        "Streaming writeback interrupted; partial content may have been written.",
      );
    }
    throw error;
  }
}

function buildStreamingWritebackPrompt(
  kind: StreamingWritebackKind,
  preparedSectionEdit: PreparedStreamingSectionEdit | null,
  retry = false,
  options: {
    missionPrompt?: string;
    activeBasename?: string;
    expandExistingDraft?: boolean;
  } = {},
): string {
  const retryPrefix = retry
    ? [
        "Previous stream failed the output contract or returned no writable markdown.",
        "Re-emit the FULL answer using the OUTPUT CONTRACT. First character must be #.",
      ]
    : [];

  if (kind === "edit") {
    return [
      ...retryPrefix,
      `Write the replacement markdown body for the section "${preparedSectionEdit?.heading ?? "target section"}" now.`,
      "Do not include the heading line itself.",
      "Use English unless the user explicitly requested another language in the current mission.",
      FINAL_ENGLISH_ONLY_RULE,
      "Return only the markdown body that belongs under that heading.",
      "Do not include preambles, explanations, receipts, or thinking traces.",
    ].join(" ");
  }

  const basename = options.activeBasename?.trim() || "current note";
  const isPlaceholder = isPlaceholderNoteBasename(basename);
  const mission =
    typeof options.missionPrompt === "string" && options.missionPrompt.trim()
      ? truncateForPromptAnchor(options.missionPrompt)
      : "";
  const pluginBehavior = isPlaceholder
    ? [
        "PLUGIN BEHAVIOR (do not re-implement):",
        "- The plugin appends/replaces this markdown into the active note.",
        "- Your leading H1 is title metadata: the plugin removes it from the note body and renames a placeholder file (Untitled / Untitled N) from it after writeback.",
        "- Do not call rename_current_file, retitle_current_file, or any tool during this writeback turn.",
      ].join("\n")
    : [
        "PLUGIN BEHAVIOR (do not re-implement):",
        "- The plugin appends/replaces this markdown into the active note.",
        "- Your leading H1 is title metadata and is not stored as a second heading in the note body.",
        "- Do not rename the file; the note already has a real title.",
        "- Do not call rename_current_file, retitle_current_file, or any tool during this writeback turn.",
      ].join("\n");

  const expandExistingDraft = Boolean(options.expandExistingDraft);
  const actionLine =
    kind === "replace"
      ? expandExistingDraft
        ? "Expand the under-target CURRENT DRAFT to meet the word target. Return the full replacement markdown for the current note (do not append a second essay)."
        : "Write the full replacement markdown for the current note now."
      : "Write the markdown content to append to the current note now.";

  return [
    ...retryPrefix,
    actionLine,
    "OUTPUT CONTRACT (follow exactly):",
    "1. Line 1 MUST be exactly one Markdown H1: # <Title>",
    "2. Line 2 MUST be blank.",
    "3. Line 3+ is the note body only.",
    '4. Return ONLY that markdown. No preamble, no tool JSON, no receipts, no "here is", no thinking.',
    "TITLE RULES:",
    "- <Title> is a short human note title (about 3-8 words), derived from the user mission.",
    '- Do not use Untitled, Untitled N, or generic titles like "Notes" / "Response" / "Answer".',
    "- Do not put the title only as ## H2 or bold text; the first line must be # H1.",
    "- Do not repeat the same H1 later in the body.",
    pluginBehavior,
    `ACTIVE NOTE: ${basename}`,
    mission ? `USER MISSION: ${JSON.stringify(mission)}` : "",
    expandExistingDraft
      ? "Keep the same topic, thesis, and useful passages from CURRENT DRAFT while lengthening to the word target."
      : "",
    "GOOD:",
    "# Hello World in TypeScript",
    "",
    'console.log("Hello, world!");',
    "BAD:",
    "Here is the content:",
    "# Hello World in TypeScript",
    "BAD:",
    "## Hello World in TypeScript",
    "BAD:",
    '{"tool":"rename_current_file","title":"..."}',
    "Use English unless the user explicitly requested another language in the current mission.",
    FINAL_ENGLISH_ONLY_RULE,
  ]
    .filter(Boolean)
    .join("\n");
}

/** Exported for unit tests of the Grok writeback contract. */
export function buildStreamingWritebackPromptForTests(
  kind: StreamingWritebackKind,
  options: {
    retry?: boolean;
    missionPrompt?: string;
    activeBasename?: string;
    expandExistingDraft?: boolean;
    preparedSectionEdit?: PreparedStreamingSectionEdit | null;
  } = {},
): string {
  return buildStreamingWritebackPrompt(
    kind,
    options.preparedSectionEdit ?? null,
    options.retry ?? false,
    {
      missionPrompt: options.missionPrompt,
      activeBasename: options.activeBasename,
      expandExistingDraft: options.expandExistingDraft,
    },
  );
}

function shouldEmitPlaceholderTitleWriteHint(input: {
  missionIntent: MissionIntent;
  streamingWritebackKind: StreamingWritebackKind | null;
  allowedToolNames: Set<string>;
  activeBasename?: string;
}): boolean {
  if (input.streamingWritebackKind !== null) {
    return false;
  }
  if (!input.missionIntent.noteOutput && !input.missionIntent.requireWriteCompletion) {
    return false;
  }
  const hasWriteTool =
    input.allowedToolNames.has("append_to_current_file") ||
    input.allowedToolNames.has("replace_current_file");
  if (!hasWriteTool) {
    return false;
  }
  return (
    !input.activeBasename ||
    isPlaceholderNoteBasename(input.activeBasename)
  );
}

interface WordCountTarget {
  target: number;
  exact: boolean;
  min: number;
  max: number;
}

function containsRecoverableToolRequest(
  content: string,
  knownToolNames: Set<string>,
): boolean {
  if (!content.trim()) {
    return false;
  }

  return (
    /<requested_tool_call\b/i.test(content) ||
    extractToolCallsFromAssistantText(content, knownToolNames).length > 0
  );
}

function createLiveWritebackEmitter({
  events,
  writer,
  knownToolNames,
  relevancePrompt,
  lifecycle,
}: {
  events: AgentRunEvents;
  writer: Awaited<ReturnType<typeof createStreamingNoteWriter>>;
  knownToolNames: Set<string>;
  relevancePrompt?: string;
  lifecycle: ReturnType<typeof createStreamLifecycleTracker>;
}) {
  let safetyBuffer = "";
  let live = false;
  let wroteContent = false;
  let toolRequestDetected = false;
  const writeSession: StreamWriteSession = createStreamWriteSession();
  const relevanceGate = createFinalAnswerRelevanceGate(relevancePrompt, events);
  const englishGuard = isLikelyEnglishPrompt(relevancePrompt ?? "");

  const emit = (delta: string) => {
    if (!delta) {
      return;
    }

    if (writeSession.released && shouldAbortReleasedChunk(writeSession, delta)) {
      toolRequestDetected = true;
      lifecycle.mark("buffering_safety", "Aborted writeback: tool markup after release.", {
        bufferedChars: delta.length,
      });
      events.onStatus?.(
        "Writeback aborted: cloud stream injected tool-call markup after note bytes were applied. Partial write kept; retry will not re-stream from byte 0.",
      );
      return;
    }

    const topicalDelta = relevanceGate.push(delta);
    if (!topicalDelta) {
      lifecycle.mark("buffering_safety", "Checking early output before writing...", {
        bufferedChars: delta.length,
      });
      return;
    }

    if (englishGuard) {
      assertEnglishOnlyVisibleOutput(topicalDelta, events);
    }

    wroteContent = true;
    recordAppliedBytes(writeSession, topicalDelta);
    lifecycle.mark("first_visible_content", "Showing safe answer text...", {
      releasedChars: topicalDelta.length,
    });
    lifecycle.mark("first_note_write", "Writing safe content to note...", {
      releasedChars: topicalDelta.length,
    });
    events.onFinalDelta?.(topicalDelta);
    events.onAssistantDelta?.(topicalDelta);
    writer.push(topicalDelta);
  };

  return {
    push(delta: string) {
      if (!delta || toolRequestDetected) {
        return;
      }

      if (live) {
        if (safetyBuffer) {
          safetyBuffer += delta;

          if (containsRecoverableToolRequest(safetyBuffer, knownToolNames)) {
            toolRequestDetected = true;
            safetyBuffer = "";
            return;
          }

          if (shouldKeepPostReleaseBuffer(safetyBuffer)) {
            lifecycle.mark("buffering_safety", "Checking possible tool output before writing...", {
              bufferedChars: safetyBuffer.length,
            });
            return;
          }

          emit(safetyBuffer);
          safetyBuffer = "";
          return;
        }

        if (containsRecoverableToolRequest(delta, knownToolNames)) {
          toolRequestDetected = true;
          return;
        }

        if (shouldKeepPostReleaseBuffer(delta)) {
          safetyBuffer = delta;
          lifecycle.mark("buffering_safety", "Checking possible tool output before writing...", {
            bufferedChars: safetyBuffer.length,
          });
          return;
        }

        emit(delta);
        return;
      }

      safetyBuffer += delta;

      if (containsRecoverableToolRequest(safetyBuffer, knownToolNames)) {
        toolRequestDetected = true;
        safetyBuffer = "";
        return;
      }

      if (shouldKeepWritebackSafetyBuffer(safetyBuffer)) {
        lifecycle.mark("buffering_safety", "Checking early output before writing...", {
          bufferedChars: safetyBuffer.length,
        });
        return;
      }

      live = true;
      emit(safetyBuffer);
      safetyBuffer = "";
    },
    finish() {
      if (safetyBuffer && !toolRequestDetected) {
        if (containsRecoverableToolRequest(safetyBuffer, knownToolNames)) {
          toolRequestDetected = true;
          safetyBuffer = "";
        } else {
          live = true;
          emit(safetyBuffer);
          safetyBuffer = "";
        }
      }

      if (!toolRequestDetected) {
        const trailingTopicalContent = relevanceGate.finish();
        if (trailingTopicalContent) {
          if (
            writeSession.released &&
            shouldAbortReleasedChunk(writeSession, trailingTopicalContent)
          ) {
            toolRequestDetected = true;
          } else {
            wroteContent = true;
            recordAppliedBytes(writeSession, trailingTopicalContent);
            events.onFinalDelta?.(trailingTopicalContent);
            events.onAssistantDelta?.(trailingTopicalContent);
            writer.push(trailingTopicalContent);
          }
        }
      }

      return {
        toolRequestDetected,
        wroteContent,
        writeSession,
        retryPolicy: createIdempotentStreamRetryPolicy(writeSession),
      };
    },
    getWriteSession: () => writeSession,
  };
}

function shouldKeepWritebackSafetyBuffer(content: string): boolean {
  const trimmed = content.trimStart();

  if (!trimmed) {
    return true;
  }

  const lower = trimmed.toLowerCase();
  if ("<requested_tool_call".startsWith(lower)) {
    return true;
  }

  if (lower.startsWith("<requested_tool_call")) {
    return true;
  }

  if (
    (trimmed.startsWith("`") || trimmed.startsWith("\\`")) &&
    !/\n/.test(trimmed)
  ) {
    return true;
  }

  if (/^\\?`\\?`?\\?`?\s*(json|tool|tool_call|function)?\s*$/i.test(trimmed)) {
    return true;
  }

  if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
    return true;
  }

  return false;
}

function shouldKeepPostReleaseBuffer(content: string): boolean {
  return shouldKeepPostReleaseBufferFromGuard(content);
}

function isInvalidResponseError(error: unknown): boolean {
  return (
    error instanceof ModelClientError &&
    error.category === "invalid_response"
  );
}

function parseWritebackWordCountTargetFromMessages(
  messages: ModelChatMessage[],
): WordCountTarget | null {
  const activeGeneratedTargetContext = [...messages]
    .reverse()
    .find(
      (message) =>
        message.role === "system" &&
        /Generated output word target:/i.test(message.content),
    );
  if (activeGeneratedTargetContext) {
    return parseWordCountTarget(activeGeneratedTargetContext.content);
  }

  const latestUserMessage = [...messages]
    .reverse()
    .find((message) => message.role === "user");
  if (
    !latestUserMessage ||
    (!hasGeneratedWritingIntent(latestUserMessage.content) &&
      !hasWordCountShortfallFollowUp(latestUserMessage.content))
  ) {
    return null;
  }

  return parseWordCountTarget(latestUserMessage.content);
}

function hasUnclosedFence(content: string): boolean {
  return (content.match(/```/g)?.length ?? 0) % 2 === 1;
}

function parseGeneratedWordCountTargetFromMessages(
  messages: ModelChatMessage[],
): WordCountTarget | null {
  const latestUserMessage = [...messages]
    .reverse()
    .find((message) => message.role === "user");
  if (
    !latestUserMessage ||
    (!hasGeneratedWritingIntent(latestUserMessage.content) &&
      !hasWordCountShortfallFollowUp(latestUserMessage.content))
  ) {
    return null;
  }

  return parseWordCountTarget(latestUserMessage.content);
}

function parseWordCountTarget(content: string): WordCountTarget | null {
  const systemTarget =
    /Generated output word target:\s*(\d{1,5})\s*words?/i.exec(content);
  const systemMin = /Word target min:\s*(\d+)/i.exec(content);
  const systemMax = /Word target max:\s*(\d+)/i.exec(content);
  if (systemTarget && systemMin && systemMax) {
    const target = Number(systemTarget[1]);
    return {
      target,
      exact: /Exact word target:\s*yes/i.test(content),
      min: Number(systemMin[1]),
      max: Number(systemMax[1]),
    };
  }

  const policy = analyzeGeneratedOutputPrompt(content).wordTarget;
  if (!policy) {
    // Fall back for shortfall follow-ups that only name a count.
    const countMatch =
      /\b(\d{1,5})\s*(?:-| )?words?\b/i.exec(content) ??
      /\b(\d{1,5})\s*(?:-| )?word\b/i.exec(content);
    if (!countMatch) {
      return null;
    }
    const target = Number(countMatch[1]);
    if (!Number.isFinite(target) || target <= 0) {
      return null;
    }
    const exact = /\b(exactly|precisely)\b/i.test(content);
    const approximate =
      /\b(about|around|approximately|roughly)\s+(\d{1,5})\s*words?\b/i.test(
        content,
      ) ||
      /\b(\d{1,5})\s*words?\s+(?:or\s+so|approximately|roughly)\b/i.test(
        content,
      );
    const bounds = resolveWordCountBounds({
      target,
      exact,
      tolerancePct: exact ? 0 : 10,
      floorAtTarget: !exact && !approximate,
    });
    return { target, exact, ...bounds };
  }

  const bounds = resolveWordCountBounds(policy);
  return {
    target: policy.target,
    exact: policy.exact,
    min: bounds.min,
    max: bounds.max,
  };
}

/**
 * Soft ±5% acceptance band used for word-count correction gating.
 * Near-miss drafts inside this band keep the written note without a rewrite pass.
 */
export function softWordCountCorrectionBand(target: number): {
  min: number;
  max: number;
  band: number;
} {
  const band = Math.max(1, Math.round(target * 0.05));
  return {
    min: Math.max(1, target - band),
    max: target + band,
    band,
  };
}

/**
 * Word-count correction uses a soft ±5% band around the stated target so a
 * near-miss draft (e.g. 3826/4000) keeps the written note instead of firing a
 * correction that historically risked appending a second essay. Exact targets
 * still require an exact count. Floor-at-target remains for resume/shortfall
 * expand bounds via resolveWordCountBounds.
 */
function shouldRequestWordCountCorrection(
  count: number,
  wordTarget: WordCountTarget,
): boolean {
  if (wordTarget.exact) {
    return count !== wordTarget.target;
  }
  const soft = softWordCountCorrectionBand(wordTarget.target);
  return count < soft.min || count > soft.max;
}

async function requestWordCountCorrection({
  modelClient,
  messages,
  draft,
  wordTarget,
  currentCount,
  events,
  think,
  options,
  abortSignal,
  onThinkingUnsupported,
  metricName,
}: {
  modelClient: ModelClient;
  messages: ModelChatMessage[];
  draft: string;
  wordTarget: WordCountTarget;
  currentCount: number;
  events: AgentRunEvents;
  think?: ModelThink;
  options?: ModelRequestOptions;
  abortSignal?: AbortSignal;
  onThinkingUnsupported: () => void;
  metricName: string;
}): Promise<string> {
  const request: ModelChatRequest = {
    messages: [
      ...messages,
      {
        role: "assistant" as const,
        content: draft,
      },
      {
        role: "user" as const,
        content: buildWordCountCorrectionPrompt(wordTarget, currentCount),
      },
    ],
    think: undefined,
    options,
    abortSignal,
    evidencePhase: "retry",
  };
  const requestChars = measureSerializedChars(request);
  const startedAt = nowMs();

  emitModelCallTrace(events, {
    id: `model-call-${metricName}`,
    message: `Model chat: ${metricName}`,
    request,
  });

  try {
    const response = await chatWithThinkingFallback({
      modelClient,
      request,
      events,
      onThinkingUnsupported,
    });
    emitMetricEvent(events, {
      kind: "model_chat",
      name: metricName,
      durationMs: elapsedMs(startedAt),
      requestChars,
      responseChars: measureSerializedChars(response.raw ?? response.message),
      ...extractTokenUsageFields(response.raw),
    });
    emitThinking(response.message.thinking, events);
    const sanitized = sanitizeAssistantContent(response.message.content);
    const corrected = stripLeadingVaultWriteToolArtifact(sanitized);
    if (corrected !== sanitized) {
      events.onStatus?.(
        "Removed a model-emitted write-tool marker from the corrected draft.",
      );
    }
    return corrected;
  } catch (error) {
    emitMetricEvent(events, {
      kind: "model_chat",
      name: metricName,
      durationMs: elapsedMs(startedAt),
      requestChars,
    });
    throw error;
  }
}

async function repairEnglishOnlyOutput({
  modelClient,
  messages,
  draft,
  events,
  think,
  options,
  abortSignal,
  onThinkingUnsupported,
  metricName,
}: {
  modelClient: ModelClient;
  messages: ModelChatMessage[];
  draft: string;
  events: AgentRunEvents;
  think?: ModelThink;
  options?: ModelRequestOptions;
  abortSignal?: AbortSignal;
  onThinkingUnsupported: () => void;
  metricName: string;
}): Promise<string> {
  const language = inspectEnglishOnlyOutput(draft);
  if (language.ok) {
    return draft;
  }

  events.onStreamLifecycle?.({
    kind: "buffering_language",
    elapsedMs: 0,
    bufferedChars: draft.length,
    message: "Language gate retrying English-only output...",
  });
  events.onStatus?.("Model produced non-English output; requesting English-only repair...");

  const repairOptions: ModelRequestOptions = {
    ...(options ?? {}),
    temperature: 0.1,
    top_p: 0.8,
  };
  const request: ModelChatRequest = {
    messages: [
      ...messages,
      {
        role: "assistant" as const,
        content: draft,
      },
      {
        role: "user" as const,
        content: buildEnglishOnlyRepairPrompt(),
      },
    ],
    think,
    options: repairOptions,
    abortSignal,
    evidencePhase: "retry",
  };
  const requestChars = measureSerializedChars(request);
  const startedAt = nowMs();

  emitModelCallTrace(events, {
    id: `model-call-${metricName}`,
    message: `Model chat: ${metricName}`,
    request,
  });

  try {
    const response = await chatWithThinkingFallback({
      modelClient,
      request,
      events,
      onThinkingUnsupported,
    });
    emitMetricEvent(events, {
      kind: "model_chat",
      name: metricName,
      durationMs: elapsedMs(startedAt),
      requestChars,
      responseChars: measureSerializedChars(response.raw ?? response.message),
      ...extractTokenUsageFields(response.raw),
    });
    emitThinking(response.message.thinking, events);
    const repaired = sanitizeAssistantContent(response.message.content);
    assertEnglishOnlyOutput(repaired);
    return repaired;
  } catch (error) {
    emitMetricEvent(events, {
      kind: "model_chat",
      name: metricName,
      durationMs: elapsedMs(startedAt),
      requestChars,
    });
    throw error;
  }
}

async function chatWithThinkingFallback({
  modelClient,
  request,
  events,
  onThinkingUnsupported,
}: {
  modelClient: ModelClient;
  request: ModelChatRequest;
  events: AgentRunEvents;
  onThinkingUnsupported: () => void;
}): Promise<ModelChatResponse> {
  try {
    return await withModelWaitStatus(
      () => modelClient.chat(request),
      events,
      "word-count correction",
    );
  } catch (error) {
    if (request.think === undefined || !isThinkingUnsupportedError(error)) {
      throw error;
    }

    onThinkingUnsupported();
    return withModelWaitStatus(
      () => modelClient.chat({
        ...request,
        think: undefined,
        evidencePhase: "retry",
      }),
      events,
      "word-count correction retry",
    );
  }
}

function buildWordCountCorrectionPrompt(
  target: WordCountTarget,
  currentCount: number,
): string {
  const soft = softWordCountCorrectionBand(target.target);
  const under = currentCount < soft.min;
  const over = currentCount > soft.max;
  const delta = under
    ? Math.max(1, soft.min - currentCount)
    : over
      ? Math.max(1, currentCount - soft.max)
      : 0;

  const lengthGoal = target.exact
    ? `exactly ${target.target} words`
    : `within the soft ±5% band of ${soft.min}–${soft.max} words (target ${target.target})`;

  const editStrategy = under
    ? [
        `The current draft is about ${currentCount} words — roughly ${delta}+ words short of the soft band.`,
        "Prefer expand-in-place: reread the existing draft, keep its structure and wording, and edit thin sections by adding sentences, examples, analysis, or transitions until the count is inside the soft band.",
        "Do not discard the draft and rewrite from scratch. Do not start a second essay after the first.",
      ].join(" ")
    : over
      ? [
          `The current draft is about ${currentCount} words — roughly ${delta}+ words over the soft band.`,
          "Prefer edit-in-place: trim redundancy and tighten phrasing while preserving the same claims, citations, and useful detail.",
          "Do not discard the draft and rewrite from scratch.",
        ].join(" ")
      : [
          "Edit the existing draft in place to satisfy the length goal.",
          "Do not discard the draft and rewrite from scratch.",
        ].join(" ");

  return [
    `Revise the previous draft to be ${lengthGoal}.`,
    editStrategy,
    "Keep the same topic, claims, citations, and useful details.",
    "Return only one complete revised note body that replaces the previous draft.",
  ].join(" ");
}

/** Exported for unit tests of expand-in-place word-count correction copy. */
export function buildWordCountCorrectionPromptForTests(
  target: {
    target: number;
    exact?: boolean;
    min?: number;
    max?: number;
  },
  currentCount: number,
): string {
  return buildWordCountCorrectionPrompt(
    {
      target: target.target,
      exact: target.exact === true,
      min: target.min ?? target.target,
      max: target.max ?? target.target,
    },
    currentCount,
  );
}

function consumeLeadingH1Title(buffer: string, force = false): LeadingTitleResult {
  const leadingBlank = /^(?:[ \t]*\r?\n)*/.exec(buffer)?.[0] ?? "";
  const candidate = buffer.slice(leadingBlank.length);
  if (!candidate) {
    return force ? { status: "no_title", body: buffer } : { status: "pending" };
  }

  if (
    !/^(?: {0,3})#(?:[ \t]|$)/.test(candidate) ||
    /^(?: {0,3})##/.test(candidate)
  ) {
    return { status: "no_title", body: buffer };
  }

  const newlineMatch = /\r?\n/.exec(candidate);
  if (!newlineMatch && !force) {
    return { status: "pending" };
  }

  const lineEnd = newlineMatch?.index ?? candidate.length;
  const line = candidate.slice(0, lineEnd).trimEnd();
  const match = /^(?: {0,3})#(?:[ \t]+)(.+?)(?:[ \t]+#+)?[ \t]*$/.exec(
    line,
  );
  if (!match) {
    return { status: "no_title", body: buffer };
  }

  const newlineLength = newlineMatch?.[0].length ?? 0;
  const bodyStart = leadingBlank.length + lineEnd + newlineLength;
  const body = buffer.slice(bodyStart).replace(/^(?:[ \t]*\r?\n)+/, "");
  return {
    status: "title",
    title: match[1].trim(),
    body,
  };
}

async function createStreamingNoteWriter({
  kind,
  toolContext,
  preparedSectionEdit,
  lazyCreatePath,
  onNoteCreated,
}: {
  kind: StreamingWritebackKind;
  toolContext: ToolExecutionContext;
  preparedSectionEdit: PreparedStreamingSectionEdit | null;
  lazyCreatePath?: string | null;
  onNoteCreated?: (file: { path: string; basename: string }) => void;
}) {
  let file: ReturnType<typeof getActiveMarkdownFile> | null = null;
  let current = "";
  let createReceiptPath: string | null = null;
  const ensureFile = async () => {
    if (file) {
      return file;
    }
    if (lazyCreatePath) {
      const created = await createAutonomousNoteTarget({
        app: toolContext.app,
        path: lazyCreatePath,
        initialContent: "",
      });
      file = created.file;
      current = "";
      createReceiptPath = created.path;
      onNoteCreated?.({ path: created.path, basename: created.file.basename });
      return file;
    }
    file = getActiveMarkdownFile(toolContext);
    current =
      toolContext.getCurrentMarkdownContent?.(file) ??
      (await toolContext.app.vault.read(file));
    return file;
  };
  if (!lazyCreatePath) {
    file = getActiveMarkdownFile(toolContext);
    current =
      toolContext.getCurrentMarkdownContent?.(file) ??
      (await toolContext.app.vault.read(file));
  }
  const makeAppendBase = (content: string) =>
    `${content}${content.length > 0 && !content.endsWith("\n") ? "\n" : ""}`;
  const getLatestAppendBaseSource = () => {
    const source =
      (file && toolContext.getCurrentMarkdownContent?.(file)) ?? current;
    // Live flushes write base+streamed. Callers that refresh the append base
    // (title metadata, replaceContent) must not treat the in-flight draft as
    // permanent note content or word-count corrections will double-append.
    if (
      kind === "append" &&
      streamedContent.length > 0 &&
      source.endsWith(streamedContent)
    ) {
      return source.slice(0, source.length - streamedContent.length);
    }
    return source;
  };
  const makeTitleMetadataAppendBase = () => {
    const source = getLatestAppendBaseSource();
    const heading = getFirstH1(source);
    return makeAppendBase(
      heading && isGenericBasename(heading.text)
        ? removeFirstH1(source)
        : source,
    );
  };
  let baseContent = kind === "append" ? makeAppendBase(current) : "";
  let baseContentChanged = false;
  let leadingTitleBuffer: string | null = kind === "edit" ? null : "";
  let extractedLeadingTitle: string | null = null;
  const backupPath =
    kind === "replace" && file
      ? await backupActiveFile(toolContext, file, current)
      : kind === "edit"
        ? requirePreparedSectionEdit(preparedSectionEdit).backupPath
        : undefined;
  const section = kind === "edit" ? requirePreparedSectionEdit(preparedSectionEdit) : null;
  let streamedContent = "";
  let pendingChars = 0;
  let lastFlushAt = nowMs();
  let flushChain = Promise.resolve();
  let flushTimer: ReturnType<typeof setTimeout> | null = null;
  let hasQueuedWrite = false;

  const render = () => {
    if (kind === "append") {
      return `${baseContent}${streamedContent}`;
    }

    if (kind === "replace") {
      return streamedContent;
    }

    return `${section?.prefix ?? ""}${formatStreamingSectionBody(
      streamedContent,
      section?.suffix ?? "",
    )}${section?.suffix ?? ""}`;
  };
  const hasWritableContent = () => streamedContent.trim().length > 0;
  const hasNoteMutation = () => baseContentChanged || hasWritableContent();
  const writeContent = async (content: string) => {
    const target = await ensureFile();
    toolContext.setCurrentMarkdownContent?.(target, content, {
      followStreamingEnd: true,
    });
    await toolContext.app.vault.modify(target, content);
  };
  const consumeLeadingTitleIfPresent = (
    delta: string,
    force = false,
  ): string => {
    if (leadingTitleBuffer === null) {
      return delta;
    }

    leadingTitleBuffer += delta;
    const titleResult = consumeLeadingH1Title(leadingTitleBuffer, force);
    if (titleResult.status === "pending") {
      return "";
    }

    leadingTitleBuffer = null;
    if (titleResult.status === "title") {
      extractedLeadingTitle = titleResult.title;
      if (kind === "append") {
        const nextBaseContent = makeTitleMetadataAppendBase();
        baseContentChanged ||= nextBaseContent !== baseContent;
        baseContent = nextBaseContent;
      }
      return titleResult.body;
    }

    return titleResult.body;
  };

  const queueFlush = () => {
    if (flushTimer !== null) {
      clearTimeout(flushTimer);
      flushTimer = null;
    }
    // Never flush process-narration into a replace stream — that wipes drafts.
    if (
      (kind === "replace" || kind === "append") &&
      isVaultWriteProcessNarration(streamedContent)
    ) {
      throw new Error(
        "Refused streamed writeback: model emitted process narration instead of note body. Existing note left unchanged.",
      );
    }
    pendingChars = 0;
    lastFlushAt = nowMs();
    const nextContent = render();
    hasQueuedWrite = true;
    flushChain = flushChain.then(() => writeContent(nextContent));
  };

  const scheduleFlush = () => {
    if (flushTimer !== null || pendingChars <= 0) {
      return;
    }

    flushTimer = setTimeout(() => {
      flushTimer = null;
      if (pendingChars > 0) {
        queueFlush();
      }
    }, LIVE_FLUSH_TIMER_MS);
  };

  return {
    push(delta: string) {
      const writableDelta = consumeLeadingTitleIfPresent(delta);
      if (!writableDelta) {
        return;
      }

      streamedContent += writableDelta;
      pendingChars += writableDelta.length;

      // Hold replace flushes while the model is narrating tool availability —
      // an early 120-char flush would wipe the existing draft.
      if (
        kind === "replace" &&
        looksLikeProcessNarrationLead(streamedContent) &&
        streamedContent.length < 700
      ) {
        if (isVaultWriteProcessNarration(streamedContent)) {
          throw new Error(
            "Refused streamed replace: model emitted process narration instead of note body. Existing note left unchanged.",
          );
        }
        scheduleFlush();
        return;
      }

      if (
        pendingChars >= LIVE_FLUSH_CHAR_THRESHOLD ||
        nowMs() - lastFlushAt >= LIVE_FLUSH_MS
      ) {
        queueFlush();
      } else {
        scheduleFlush();
      }
    },
    replaceContent(content: string) {
      // Keep the session append base. Never refresh baseContent from the live
      // note here — mid-stream flushes already contain the previous draft, and
      // re-running title/base extraction would append a second essay after it.
      if (kind !== "edit") {
        leadingTitleBuffer = null;
        const titleResult = consumeLeadingH1Title(content, true);
        if (titleResult.status === "title") {
          extractedLeadingTitle = titleResult.title;
          streamedContent = titleResult.body;
        } else if (titleResult.status === "no_title") {
          extractedLeadingTitle = null;
          streamedContent = titleResult.body;
        } else {
          extractedLeadingTitle = null;
          streamedContent = content;
        }
      } else {
        streamedContent = content;
      }
      pendingChars = streamedContent.length;
      queueFlush();
    },
    softResetStreamedDraft() {
      // Clear the in-session draft buffer without writing an empty note. The
      // prior flushed draft stays on disk until the next push/replaceContent.
      if (flushTimer !== null) {
        clearTimeout(flushTimer);
        flushTimer = null;
      }
      streamedContent = "";
      pendingChars = 0;
      leadingTitleBuffer = kind === "edit" ? null : "";
      extractedLeadingTitle = null;
    },
    hasWritableContent() {
      return hasNoteMutation();
    },
    discardNonWritableContent() {
      if (hasNoteMutation()) {
        return;
      }

      if (flushTimer !== null) {
        clearTimeout(flushTimer);
        flushTimer = null;
      }
      streamedContent = "";
      pendingChars = 0;
      leadingTitleBuffer = kind === "edit" ? null : "";
      extractedLeadingTitle = null;
    },
    async finish(options: { force?: boolean } = {}) {
      const trailingTitleContent = consumeLeadingTitleIfPresent("", true);
      if (trailingTitleContent) {
        streamedContent += trailingTitleContent;
        pendingChars += trailingTitleContent.length;
      }
      if (flushTimer !== null) {
        clearTimeout(flushTimer);
        flushTimer = null;
      }
      // Process narration only here — short-replace checks run on final commit
      // paths so mid-stream partials / interrupt finish do not false-trip.
      if (
        (kind === "replace" || kind === "append") &&
        isVaultWriteProcessNarration(streamedContent)
      ) {
        throw new Error(
          "Refused to write model process narration into the note. Existing note left unchanged when nothing was flushed yet.",
        );
      }
      if (
        hasNoteMutation() &&
        (pendingChars > 0 || (options.force && !hasQueuedWrite))
      ) {
        queueFlush();
      }
      await flushChain;
    },
    async buildReceipt(partial: boolean): Promise<AgentRunReceipt> {
      const resolvedPath = file?.path ?? lazyCreatePath ?? "unknown";
      const operation =
        kind === "append" ? "append" : kind === "replace" ? "replace" : "edit";
      const bytesWritten =
        kind === "append" ? getByteLength(streamedContent) : getByteLength(render());
      const target = await ensureFile();
      const expectedContent = render();
      const observedContent = await toolContext.app.vault.read(target);
      if (observedContent !== expectedContent) {
        throw new Error(
          `Streamed ${operation} readback did not match the committed note content.`,
        );
      }
      const checkedAt = (toolContext.now?.() ?? new Date()).toISOString();
      const readback: ActionReceipt["readback"] = {
        status: "verified",
        checkedAt,
        observedRevision: hashOperationInput({
          path: resolvedPath,
          content: observedContent,
        }),
        observedFingerprint: hashOperationInput(observedContent),
      };
      const output = {
        path: resolvedPath,
        operation,
        backupPath,
        bytesWritten,
        readback,
        streamed: true,
        partial,
        heading: section?.heading,
        level: section?.level,
        ...(extractedLeadingTitle
          ? { leadingTitle: extractedLeadingTitle }
          : {}),
        ...(createReceiptPath ? { createdPath: createReceiptPath } : {}),
      };

      const messageParts = [`${operation} ${resolvedPath}`];
      if (createReceiptPath) {
        messageParts.push(`created: ${createReceiptPath}`);
      }
      if (backupPath) {
        messageParts.push(`backup: ${backupPath}`);
      }
      if (partial) {
        messageParts.push("partial");
      }

      return {
        toolName:
          kind === "append"
            ? "append_to_current_file"
            : kind === "replace"
              ? "replace_current_file"
              : "edit_current_section",
        operation,
        path: resolvedPath,
        backupPath,
        bytesWritten: output.bytesWritten,
        readback,
        output,
        message: messageParts.join("; "),
      };
    },
  };
}

function parsePreparedStreamingSectionEdit(
  output: unknown,
): PreparedStreamingSectionEdit {
  if (!isRecord(output)) {
    throw new Error("prepare_edit_current_section returned an invalid result.");
  }

  const path = getString(output.path);
  const backupPath = getString(output.backupPath);
  const heading = getString(output.heading);
  const prefix = getString(output.prefix);
  const suffix = typeof output.suffix === "string" ? output.suffix : "";
  const level = getNumber(output.level);
  const replacedChars = getNumber(output.replacedChars);

  if (!path || !backupPath || !heading || !prefix || level === undefined) {
    throw new Error("prepare_edit_current_section returned incomplete section data.");
  }

  return {
    path,
    backupPath,
    heading,
    level,
    prefix,
    suffix,
    replacedChars: replacedChars ?? 0,
  };
}

function requirePreparedSectionEdit(
  preparedSectionEdit: PreparedStreamingSectionEdit | null,
): PreparedStreamingSectionEdit {
  if (!preparedSectionEdit) {
    throw new Error("Streaming section edit requires prepare_edit_current_section first.");
  }

  return preparedSectionEdit;
}

function getActiveMarkdownFile(toolContext: ToolExecutionContext) {
  const file =
    toolContext.getCurrentMarkdownFile?.() ??
    toolContext.app.workspace.getActiveFile();
  if (!file || file.extension !== "md") {
    throw new Error(
      "An active markdown file is required. Open or focus a markdown note before running the mission.",
    );
  }

  return file;
}

async function backupActiveFile(
  toolContext: ToolExecutionContext,
  file: ReturnType<typeof getActiveMarkdownFile>,
  content: string,
): Promise<string> {
  if (!toolContext.app.vault.getFolderByPath(BACKUP_FOLDER)) {
    try {
      await toolContext.app.vault.createFolder(BACKUP_FOLDER);
    } catch (error) {
      if (!isFolderAlreadyExistsError(error)) {
        throw error;
      }
    }
  }

  const timestamp = (toolContext.now?.() ?? new Date()).getTime();
  const basename = sanitizeBackupBasename(file.basename);
  let backupPath = `${BACKUP_FOLDER}/${timestamp}-${basename}.md`;
  let suffix = 1;

  while (toolContext.app.vault.getFileByPath(backupPath)) {
    backupPath = `${BACKUP_FOLDER}/${timestamp}-${basename}-${suffix}.md`;
    suffix += 1;
  }

  await toolContext.app.vault.create(backupPath, content);
  return backupPath;
}

function isFolderAlreadyExistsError(error: unknown): boolean {
  return /folder already exists|already exists/i.test(getErrorMessage(error));
}

function sanitizeBackupBasename(basename: string): string {
  const sanitized = basename.trim().replace(/[^a-zA-Z0-9._-]+/g, "-");
  return sanitized || "untitled";
}

function formatStreamingSectionBody(content: string, suffix: string): string {
  if (!content) {
    return "";
  }

  return suffix && !content.endsWith("\n") ? `${content}\n` : content;
}

function getByteLength(text: string): number {
  return new TextEncoder().encode(text).length;
}

function selectExplicitEffectfulGraphTools({
  prompt,
  allowedToolNames,
  toolRegistry,
}: {
  prompt: string;
  allowedToolNames: string[];
  toolRegistry: ToolRegistry;
}): string[] {
  const promptTokens = new Set(intentMatchTokens(prompt));
  const byAction = new Map<
    string,
    Array<{ name: string; score: number; explicitName: boolean }>
  >();
  for (const name of allowedToolNames) {
    let descriptor: ToolDescriptor;
    try {
      descriptor = toolRegistry.getDescriptor?.(name) ?? descriptorFor(name);
    } catch {
      continue;
    }
    if (descriptor.effect === "read") continue;
    const actionTokens = intentMatchTokens(descriptor.capability.action);
    if (
      actionTokens.length === 0 ||
      !actionTokens.every((token) => promptTokens.has(token))
    ) {
      continue;
    }
    const systemMatches = intentMatchTokens(descriptor.capability.system).filter(
      (token) => promptTokens.has(token),
    ).length;
    const resourceMatches = intentMatchTokens(
      descriptor.capability.resourceType ?? "",
    ).filter(
      (token) =>
        !actionTokens.includes(token) && promptTokens.has(token),
    ).length;
    const nameTokens = intentMatchTokens(name);
    const nameMatches = nameTokens.filter((token) => promptTokens.has(token)).length;
    const explicitName =
      nameTokens.length > 1 && nameTokens.every((token) => promptTokens.has(token));
    if (
      descriptor.execution.preparation === "required" &&
      !explicitName &&
      systemMatches + resourceMatches === 0
    ) {
      continue;
    }
    const score =
      100 + systemMatches * 20 + resourceMatches * 10 + nameMatches * 2;
    const key = actionTokens.join("-");
    const candidates = byAction.get(key) ?? [];
    candidates.push({ name, score, explicitName });
    byAction.set(key, candidates);
  }

  const selected: string[] = [];
  for (const candidates of byAction.values()) {
    candidates.sort(
      (left, right) =>
        Number(right.explicitName) - Number(left.explicitName) ||
        right.score - left.score ||
        left.name.localeCompare(right.name),
    );
    const best = candidates[0];
    const next = candidates[1];
    if (
      best &&
      (!next ||
        best.explicitName !== next.explicitName ||
        best.score > next.score)
    ) {
      selected.push(best.name);
    }
  }
  return selected;
}

function intentMatchTokens(value: string): string[] {
  return [
    ...new Set(
      (value.toLowerCase().match(/[a-z0-9]+/gu) ?? [])
        .map((token) =>
          token.length > 3 && token.endsWith("s") ? token.slice(0, -1) : token,
        )
        .filter(
          (token) =>
            token.length > 1 &&
            ![
              "to",
              "current",
              "tool",
              "action",
              "markdown",
            ].includes(token),
        ),
    ),
  ];
}

function isRunRouteValue(value: unknown): value is RunRoute {
  return typeof value === "string" && [
    "instant_local",
    "direct_writeback",
    "prefetched_vault_answer",
    "prefetched_vault_writeback",
    "single_model_answer",
    "single_model_writeback",
    "tool_required",
    "grounded_workflow",
  ].includes(value);
}

function missionGraphReferenceId(
  kind: "evidence" | "receipt" | "final",
  nodeId: string,
  revision: number,
): string {
  const suffix = nodeId
    .toLowerCase()
    .replace(/[^a-z0-9._:-]+/g, "-")
    .replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, "") || "node";
  return `${kind}:${Math.max(0, Math.trunc(revision))}:${suffix}`.slice(0, 128);
}

function isSafeMissionGraphReferenceId(
  value: string | null | undefined,
): value is string {
  return (
    typeof value === "string" &&
    value.length <= 128 &&
    /^[a-z0-9](?:[a-z0-9._:-]*[a-z0-9])?$/u.test(value)
  );
}

export function ensureResearchSourceLoopBudget(
  loopBudgetPlan: LoopBudgetPlan,
  minFetchedSources: number,
): LoopBudgetPlan {
  if (!Number.isFinite(minFetchedSources) || minFetchedSources <= 0) {
    return loopBudgetPlan;
  }

  const maxToolSteps = Math.max(
    0,
    loopBudgetPlan.hardCap - loopBudgetPlan.finalizationReserve,
  );
  return {
    ...loopBudgetPlan,
    toolStepBudget: Math.min(
      maxToolSteps,
      Math.max(loopBudgetPlan.toolStepBudget, minFetchedSources + 1),
    ),
    expectedTools: [
      ...new Set([
        ...loopBudgetPlan.expectedTools,
        "web_search",
        "web_fetch",
      ]),
    ],
    stopWhenSatisfied: true,
  };
}

export function ensureRequiredWriteLoopBudget(
  loopBudgetPlan: LoopBudgetPlan,
  requiredWriteTools: readonly string[],
): LoopBudgetPlan {
  const missingExpectedWrites = [...new Set(requiredWriteTools)].filter(
    (toolName) => !loopBudgetPlan.expectedTools.includes(toolName),
  );
  if (missingExpectedWrites.length === 0) {
    return loopBudgetPlan;
  }
  const maxToolSteps = Math.max(
    0,
    loopBudgetPlan.hardCap - loopBudgetPlan.finalizationReserve,
  );
  return {
    ...loopBudgetPlan,
    toolStepBudget: Math.min(
      maxToolSteps,
      // Reserve one schema-qualified correction turn in addition to the write
      // itself. Otherwise an early prose answer on the last read step makes a
      // ready authoritative mutation node unreachable.
      loopBudgetPlan.toolStepBudget + missingExpectedWrites.length + 1,
    ),
    expectedTools: [
      ...new Set([
        ...loopBudgetPlan.expectedTools,
        ...missingExpectedWrites,
      ]),
    ],
    stopWhenSatisfied: true,
  };
}

function isMissionGraphCapacityError(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    (error as { missionGraphStartCode?: unknown }).missionGraphStartCode ===
      "budget_exhausted"
  );
}

export function extractExactMarkdownReplacementPayload(
  prompt: string,
): string | null {
  const match =
    /\bexactly[ \t]+(?:this|the[ \t]+following)[ \t]+markdown[ \t]*:[ \t]*\r?\n([\s\S]+)$/iu.exec(
      prompt,
    );
  if (!match || match[1].length === 0) {
    return null;
  }
  const fenced = /^```(?:markdown|md)?[ \t]*\r?\n([\s\S]*?)\r?\n```[ \t]*$/iu.exec(
    match[1],
  );
  return fenced ? fenced[1] : match[1];
}

const LITERAL_CONTENT_WRITE_TOOLS = new Set([
  "append_to_current_file",
  "replace_current_file",
  "append_file",
  "replace_file",
  "create_file",
]);

export function validateRequiredLiteralWriteArguments(
  prompt: string,
  toolCall: ModelToolCall,
): string | null {
  if (!LITERAL_CONTENT_WRITE_TOOLS.has(toolCall.name)) {
    return null;
  }
  const anchors = extractRequiredLiteralAnchors(prompt);
  if (anchors.length === 0) {
    return null;
  }
  const content =
    typeof toolCall.arguments.text === "string"
      ? toolCall.arguments.text
      : typeof toolCall.arguments.content === "string"
        ? toolCall.arguments.content
        : null;
  if (content === null) {
    return null;
  }
  const normalizedContent = content.toLowerCase();
  const missing = anchors.filter(
    (anchor) => !normalizedContent.includes(anchor.toLowerCase()),
  );
  if (missing.length === 0) {
    return null;
  }
  return `The ${toolCall.name} content is missing ${missing.length} literal value(s) explicitly required by the mission. Return one corrected call whose content preserves every requested literal exactly.`;
}

export function sanitizeAssistantContent(content: string): string {
  return content
    .replace(
      /[<＜]\s*[|｜]\s*(?:begin\s*[_▁]+\s*of\s*[_▁]+\s*sentence|end\s*[_▁]+\s*of\s*[_▁]+\s*sentence|start\s*[_▁]+\s*header\s*[_▁]+\s*id|end\s*[_▁]+\s*header\s*[_▁]+\s*id|eot\s*[_▁]+\s*id|eom\s*[_▁]+\s*id)\s*[|｜]\s*[>＞]/gi,
      "",
    )
    // Vendor tool-call sentinels (Kimi K2 sections, Qwen/Hermes tags). The
    // recovery parser reads the RAW content first; sanitization only shapes
    // what is displayed, measured, or written back.
    .replace(
      /[<＜]\s*[|｜]\s*tool\s*[_▁]*\s*calls?\s*[_▁]*\s*(?:section\s*[_▁]*\s*)?(?:begin|end|argument\s*[_▁]*\s*begin)\s*[|｜]\s*[>＞]/gi,
      "",
    )
    .replace(/<\/?tool_call>/gi, "");
}

export function createAssistantContentSanitizer() {
  let pending = "";

  return {
    push(delta: string): string {
      pending = sanitizeAssistantContent(`${pending}${delta}`);

      const tokenStartIndex = findPotentialSpecialTokenStart(pending);
      if (tokenStartIndex < 0) {
        const output = pending;
        pending = "";
        return output;
      }

      const output = pending.slice(0, tokenStartIndex);
      pending = pending.slice(tokenStartIndex);
      return output;
    },
    flush(): string {
      const output = sanitizeAssistantContent(pending);
      pending = "";
      return output;
    },
  };
}

const NORMALIZED_SPECIAL_TOKENS = [
  "<|beginofsentence|>",
  "<|endofsentence|>",
  "<|startheaderid|>",
  "<|endheaderid|>",
  "<|eotid|>",
  "<|eomid|>",
  "<|toolcallssectionbegin|>",
  "<|toolcallssectionend|>",
  "<|toolcallbegin|>",
  "<|toolcallend|>",
  "<|toolcallargumentbegin|>",
  // normalizeSpecialTokenCandidate strips underscores before matching.
  "<toolcall>",
  "</toolcall>",
];

const SPECIAL_TOKEN_LOOKBACK_CHARS = 80;

function findPotentialSpecialTokenStart(content: string): number {
  const searchStart = Math.max(0, content.length - SPECIAL_TOKEN_LOOKBACK_CHARS);
  for (let index = searchStart; index < content.length; index += 1) {
    if (content[index] !== "<" && content[index] !== "＜") {
      continue;
    }

    const candidate = normalizeSpecialTokenCandidate(content.slice(index));

    if (
      candidate &&
      NORMALIZED_SPECIAL_TOKENS.some((token) => token.startsWith(candidate))
    ) {
      return index;
    }
  }

  return -1;
}

function normalizeSpecialTokenCandidate(candidate: string): string {
  return candidate
    .toLowerCase()
    .replace(/＜/g, "<")
    .replace(/＞/g, ">")
    .replace(/｜/g, "|")
    .replace(/\s+/g, "")
    .replace(/[_▁]+/g, "");
}

function isClarifyingQuestionResponse(prompt: string, content: string): boolean {
  const sanitized = sanitizeAssistantContent(content).trim();
  if (!/\?\s*$/.test(sanitized)) {
    return false;
  }

  if (hasAmbiguousDatePrompt(prompt)) {
    return true;
  }

  if (sanitized.length > 700) {
    return false;
  }

  return (
    /^(before i|could you|can you|would you|which|what|where|when|who|how should|do you want|should i|may i|please (?:provide|confirm|choose|tell me)|i need|i(?:'|’)ll need|to proceed|to continue)\b/i.test(
      sanitized,
    ) ||
    /\b(clarify|clarification|confirm|choose|which|what|where|when|missing|required|need(?:ed)?|target|credential|permission)\b/i.test(
      sanitized,
    )
  );
}

function hasRenderableAssistantContent(content: string): boolean {
  return sanitizeAssistantContent(content).trim().length > 0;
}

function isThinkingUnsupportedError(error: unknown): boolean {
  const text = getErrorSearchText(error);
  return (
    /\b(think|thinking|reasoning)\b/.test(text) &&
    /\b(unsupported|not supported|invalid|unknown|unrecognized|unexpected)\b/.test(
      text,
    )
  );
}

function getUnknownErrorMessage(error: unknown): string {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  if (typeof error === "string") {
    return error;
  }

  return "Unknown error";
}

function getErrorSearchText(error: unknown): string {
  const parts: string[] = [];

  if (error instanceof Error) {
    parts.push(error.message);
  } else {
    parts.push(String(error));
  }

  if (error instanceof ModelClientError) {
    parts.push(JSON.stringify(error.details ?? ""));
    parts.push(String(error.status ?? ""));
  }

  return parts.join(" ").toLowerCase();
}

/**
 * True when Bound pending tools already have an unused exact grant/approval.
 * Hard tools never match (must not silently auto-grant). Soft tools do not
 * require a grant under automatic autonomy — callers still pass the flag, but
 * mayAutoExecute ignores it for soft.
 */
export async function resolveHasMatchingGrantForAutoContinuation(input: {
  pendingToolNames: readonly string[];
  approvals?: ReadonlyArray<{
    id: string;
    toolName: string;
    decision: string;
  }>;
  receipts?: ReadonlyArray<{ toolName?: string; grantId?: string }>;
  preparedActionAuthority?: RunAgentMissionOptions["preparedActionAuthority"];
  /** When true, Bound set-loose tools count as granted without Chat approve. */
  setLooseCompound?: boolean;
}): Promise<boolean> {
  const pending = input.pendingToolNames
    .map((name) => name.trim())
    .filter(Boolean);
  if (pending.length === 0) {
    return false;
  }

  const boundPending = pending.filter(
    (toolName) => effectClassForTool(toolName) === "bound",
  );
  if (boundPending.length === 0) {
    return false;
  }

  if (input.setLooseCompound === true) {
    const allSetLoose = boundPending.every((toolName) =>
      runnerBoundMayAutoWithoutGrant({
        toolName,
        autonomyProfile: "automatic",
        compoundLifecycleDetected: true,
      }),
    );
    if (allSetLoose) {
      return true;
    }
  }

  const approvals = input.approvals ?? [];
  const receipts = input.receipts ?? [];
  for (const toolName of boundPending) {
    for (const approval of approvals) {
      if (
        approval.toolName !== toolName ||
        approval.decision !== "approved"
      ) {
        continue;
      }
      const expectedGrantId = `grant:${approval.id}`;
      const consumed = receipts.some(
        (receipt) => receipt.grantId === expectedGrantId,
      );
      if (!consumed) {
        return true;
      }
    }

    const peek = input.preparedActionAuthority?.hasUnusedGrantForTool;
    if (typeof peek === "function") {
      try {
        if (await peek(toolName)) {
          return true;
        }
      } catch {
        // Peek failures fail closed — do not invent a grant.
      }
    }
  }

  return false;
}

/**
 * Grant discovery exists only to decide whether an unfinished budget stop may
 * continue automatically. Successful and otherwise terminal runs must never
 * wait on prepared-action authority after their ledger and receipts already
 * prove the outcome.
 */
export function shouldInspectAutoContinuationGrant(
  stopReason: AgentRunStopReason,
  suppressAutoContinuation: boolean,
): boolean {
  return stopReason === "budget" && !suppressAutoContinuation;
}

function completeRun(
  events: AgentRunEvents,
  stopReason: AgentRunStopReason,
  step: number,
  runStartedAt?: number,
  maxSteps = MAX_AGENT_STEPS,
  autoContinuation?: AutoContinuationDecision,
  stopDetail?: string | null,
) {
  const message = getStopReasonMessage(stopReason);
  emitStatus(
    events,
    message,
    stopReason === "budget" || stopReason === "user_stopped"
      ? "stopped"
      : "done",
  );
  events.onRunComplete?.({
    step,
    maxSteps,
    stopReason,
    stopDetail: stopDetail ?? autoContinuation?.reason ?? null,
    ...(autoContinuation
      ? {
          autoContinueRecommended: autoContinuation.recommended,
          autoContinueReason: autoContinuation.reason,
        }
      : {}),
  });
  events.onTrace?.({
    id: `final-${stopReason}`,
    kind: "final",
    step,
    message,
    outputPreview: {
      step,
      maxSteps,
      stopReason,
      stopDetail: stopDetail ?? autoContinuation?.reason ?? null,
      autoContinueRecommended: autoContinuation?.recommended ?? false,
      autoContinueReason: autoContinuation?.reason ?? "not_budget",
    },
  });
  if (runStartedAt !== undefined) {
    emitMetricEvent(events, {
      kind: "run",
      name: "mission",
      step,
      durationMs: elapsedMs(runStartedAt),
    });
  }
}

function isToolArgumentErrorCode(code: string | undefined): boolean {
  return code === "invalid_arguments" || code?.endsWith("_invalid_arguments") === true;
}

function getStopReasonMessage(stopReason: AgentRunStopReason): string {
  // Status-stream copy stays stable for Run Details + existing tests.
  // Chat uses stopReasonChatLine() for the friendlier taxonomy.
  switch (stopReason) {
    case "write_completed":
      return "Write complete.";
    case "clarifying_question":
      return "Needs clarification.";
    case "user_stopped":
      return "Stopped by user.";
    case "budget":
      return "Stopped at safety limit. Review partial results.";
    case "error":
      return "Error.";
    case "final":
    default:
      return "Done.";
  }
}

export function buildScopedDurableEvidenceForWriteback(
  evidence: MissionEvidence[],
  researchPlan: ResearchPlan | null | undefined,
): {
  content: string;
  acceptedPassageIds: string[];
  citationScope: "fetched_web" | "vault";
} {
  const citationScope = isPureVaultCitationScope(researchPlan)
    ? "vault"
    : "fetched_web";
  const acceptedPassageIds = getAcceptedMissionPassageIds(
    evidence,
    researchPlan,
  );
  return {
    content: formatDurableEvidenceForWriteback(
      evidence,
      acceptedPassageIds,
      citationScope,
    ),
    acceptedPassageIds,
    citationScope,
  };
}

function formatDurableEvidenceForWriteback(
  evidence: MissionEvidence[],
  allowedPassageIds?: string[],
  citationScope: "fetched_web" | "vault" = "fetched_web",
): string {
  const allowed = allowedPassageIds
    ? new Set(allowedPassageIds)
    : null;
  const entries = evidence.slice(-12).map((item) => {
    const citationIds = [
      item.passageId,
      ...(item.passageIds ?? []),
      item.sourceId,
    ]
      .filter(
        (value): value is string =>
          typeof value === "string" && value.length > 0,
      )
      .filter(
        (value, index, values) =>
          values.indexOf(value) === index &&
          (allowed === null || allowed.has(value)),
      )
      .slice(0, 24);
    const locator = item.url ?? item.path ?? item.id;
    const citations =
      citationIds.length > 0
        ? ` Citation identifiers: ${citationIds.join(", ")}.`
        : "";
    return `- ${item.title} (${locator}): ${item.summary.slice(0, 800)}${citations}`;
  });
  return [
    "Verified durable mission evidence available for writeback.",
    allowed
      ? citationScope === "vault"
        ? "Only the listed durable vault passage identifiers are valid citations for this pure-vault writeback. Do not invent identifiers."
        : "Only the listed fetched-source passage identifiers are valid citations for this writeback. Vault context may inform synthesis but its internal identifiers are not citation authority."
      : "Use these exact source and passage identifiers when the final output requires citations. Do not invent identifiers.",
    ...entries,
  ].join("\n");
}

function hasRuntimeSnapshotPersistence(context: ToolExecutionContext): boolean {
  const vault = context.app?.vault;
  return Boolean(
    vault &&
      typeof vault.getFileByPath === "function" &&
      typeof vault.create === "function" &&
      typeof vault.modify === "function" &&
      typeof vault.read === "function" &&
      typeof vault.getFolderByPath === "function" &&
      typeof vault.createFolder === "function",
  );
}

function isBlockingPreWriteProof(item: string): boolean {
  return /web_evidence|source_coverage|source_domains|citation_coverage|fetched_sources|distinct_domains|vault_evidence|word_count|code_execution|research_plan_items/i.test(
    item,
  );
}

function isContentWriteToolThatNeedsEvidence(toolName: string): boolean {
  return [
    "create_file",
    "append_file",
    "replace_file",
    "append_to_current_file",
    "append_to_current_section",
    "edit_current_section",
    "replace_current_file",
    "link_related_notes_in_current_file",
    "fill_template",
    "create_template",
    "create_research_pack",
    "create_design_canvas",
    "create_svg_design",
    "create_design_package",
    "export_workspace_artifact",
  ].includes(toolName);
}

function getStreamingWritebackToolName(
  kind: StreamingWritebackKind,
): "append_to_current_file" | "replace_current_file" | "edit_current_section" {
  return kind === "append"
    ? "append_to_current_file"
    : kind === "replace"
      ? "replace_current_file"
      : "edit_current_section";
}

function requiresVerifiedFinalOutput(
  missionPlan: MissionPlan | null,
  researchPlan: ResearchPlan | null,
): boolean {
  return Boolean(
    researchPlan ||
      missionPlan?.tasks.some((task) =>
        task.completionContract.citationMode !== undefined,
      ),
  );
}

function isProofGatedCurrentNoteContentTool(toolName: string): boolean {
  return [
    "append_to_current_file",
    "append_to_current_section",
    "replace_current_file",
    "edit_current_section",
  ].includes(toolName);
}

function isRepairableFinalOutputProof(item: string): boolean {
  return (
    item === "final_output" ||
    item === "citation_url_coverage" ||
    item.startsWith("passage_citation_coverage:") ||
    item === "limitations_section" ||
    item === "confidence_section" ||
    item === "unanswered_questions" ||
    item.includes("open_evidence_conflicts") ||
    item.startsWith("subquestion_citation_coverage:") ||
    item.startsWith("verifier:citation_coverage:") ||
    item === "verifier:final_output" ||
    item === "verifier:final_relevance" ||
    item === "research_phase_acceptance:analyze" ||
    item.includes("claim_grounding") ||
    /^verifier:[^:]+:final_relevance$/u.test(item) ||
    /^plan:[^:]+:final_relevance$/u.test(item)
  );
}

function isCitationCoverageProof(item: string): boolean {
  return (
    item === "citation_url_coverage" ||
    item.startsWith("passage_citation_coverage:") ||
    item.startsWith("subquestion_citation_coverage:") ||
    item.startsWith("verifier:citation_coverage:")
  );
}

function getMissingAcceptedPassageCitationIds(
  draft: string,
  acceptedPassageIds: string[],
  researchPlan: ResearchPlan | null | undefined,
  missionPrompt: string,
): string[] {
  if (!hasClosedPassageCitationScope(researchPlan, acceptedPassageIds)) {
    return [];
  }
  if (!hasExplicitPassageCitationContract(missionPrompt)) {
    return [];
  }
  const accepted = [
    ...new Set(
      acceptedPassageIds.filter((item) =>
        /^source:[a-z0-9-]+:passage:\d+-\d+$/u.test(item),
      ),
    ),
  ];
  if (accepted.length === 0) {
    return [];
  }
  const cited = new Set(
    [...draft.matchAll(PASSAGE_CITATION_TOKEN_PATTERN)]
      .map((match) => match[1] ?? match[2] ?? "")
      .filter((item) => accepted.includes(item)),
  );
  return accepted.filter((item) => !cited.has(item));
}

function requireAcceptedPassageCitationCoverage(
  acceptance: MissionAcceptanceResult,
  draft: string,
  acceptedPassageIds: string[],
  researchPlan: ResearchPlan | null | undefined,
  missionPrompt: string,
): MissionAcceptanceResult {
  const missingPassageIds = getMissingAcceptedPassageCitationIds(
    draft,
    acceptedPassageIds,
    researchPlan,
    missionPrompt,
  );
  if (missingPassageIds.length === 0) {
    return acceptance;
  }
  const missingKey =
    `passage_citation_coverage:${missingPassageIds.join(",")}`;
  const missing = [...new Set([...acceptance.missing, missingKey])];
  return {
    ...acceptance,
    status: acceptance.status === "fail" ? "fail" : "needs_more_work",
    confidence: Math.min(acceptance.confidence, 0.55),
    missing,
    reasons: [
      ...new Set([
        ...acceptance.reasons,
        "accepted_passage_citations_missing",
      ]),
    ],
    nextAction:
      acceptance.nextAction ??
      "Cite every accepted fetched-source passage id before the note writeback can be committed.",
  };
}

function hasExplicitPassageCitationContract(prompt: string): boolean {
  return /source:<id>:passage|source:[a-z0-9-]+:passage:\d+-\d+|\bpassage[-\s]*(?:ids?|identifiers?|markers?|citations?)\b|\bexact\b[\s\S]{0,80}\bpassage(?:[-\s]*(?:ids?|identifiers?|markers?))?\b/iu.test(
    prompt,
  );
}

function getProofGatedWritebackCandidateAcceptance(
  acceptance: MissionAcceptanceResult,
  requiredWriteTools: string[],
): MissionAcceptanceResult {
  const requiredWrites = new Set(requiredWriteTools);
  const missing = acceptance.missing.filter((item) => {
    if (item === "write_receipt") {
      return false;
    }
    if (item.startsWith("tool:")) {
      return !requiredWrites.has(item.slice("tool:".length));
    }
    if (item.startsWith("pending_goal:")) {
      // The candidate is intentionally checked before its single journaled
      // commit, so the current-note write goal must still be pending here.
      return false;
    }
    if (
      /^verifier:[^:]+:(?:write_receipt|artifact_receipt|rename_receipt|highlight_receipt)$/u.test(
        item,
      ) ||
      /^plan:[^:]+:(?:write_receipt|artifact_receipt|rename_receipt|highlight_receipt)$/u.test(
        item,
      )
    ) {
      return false;
    }
    return true;
  });
  return {
    ...acceptance,
    status: missing.length === 0 ? "pass" : acceptance.status,
    missing,
    reasons:
      missing.length === 0
        ? [...new Set([...acceptance.reasons, "candidate_proof_verified_before_commit"])]
        : acceptance.reasons,
  };
}

function buildFinalOutputVerificationCorrectionPrompt(
  acceptance: MissionAcceptanceResult,
  rejectedCandidate: string,
  missionPrompt = "",
  knownPassageIds: string[] = [],
  plan: MissionPlan | null = null,
  evidence: MissionEvidence[] = [],
  researchPlan: ResearchPlan | null = null,
): string {
  const requirePassageIds = shouldRequireClaimGrounding(missionPrompt);
  const requiredLiteralAnchors = extractRequiredLiteralAnchors(missionPrompt);
  const finalRelevanceMissing = acceptance.missing.some(
    (item) => /(?:^|:)final_relevance$/u.test(item),
  );
  const acceptedPassageIds = [
    ...new Set(
      knownPassageIds.filter((item) =>
        /^source:[a-z0-9-]+:passage:\d+-\d+$/u.test(item),
      ),
    ),
  ].slice(0, 16);
  const missingCitationTaskIds = acceptance.missing.flatMap((item) => {
    const match = /^verifier:citation_coverage:(.+)$/u.exec(item);
    return match?.[1] ? [match[1]] : [];
  });
  const missingSubquestionIds = acceptance.missing.flatMap((item) => {
    const match = /^subquestion_citation_coverage:(.+)$/u.exec(item);
    return match?.[1]
      ? match[1].split(",").map((id) => id.trim()).filter(Boolean)
      : [];
  });
  const missingAcceptedPassageIds = acceptance.missing.flatMap((item) => {
    const match = /^passage_citation_coverage:(.+)$/u.exec(item);
    return match?.[1]
      ? match[1].split(",").map((id) => id.trim()).filter(Boolean)
      : [];
  });
  const missingEvidenceIds = new Set(
    [
      ...(plan?.tasks ?? [])
        .filter((task) => missingCitationTaskIds.includes(task.id))
        .flatMap((task) => task.evidenceIds),
      ...(researchPlan?.subquestions ?? [])
        .filter((item) => missingSubquestionIds.includes(item.id))
        .flatMap((item) => item.evidenceIds),
    ],
  );
  const missingPassageIds = [
    ...new Set(
      [
        ...evidence
          .filter((item) => missingEvidenceIds.has(item.id))
          .flatMap((item) => [
            ...(item.passageId ? [item.passageId] : []),
            ...(item.passageIds ?? []),
          ]),
        ...missingAcceptedPassageIds,
      ].filter((item) => acceptedPassageIds.includes(item)),
    ),
  ];
  const citationMissing = acceptance.missing.some(
    (item) =>
      item === "citation_url_coverage" ||
      item.startsWith("passage_citation_coverage:") ||
      item.startsWith("subquestion_citation_coverage:") ||
      item.startsWith("verifier:citation_coverage:") ||
      item.includes("claim_grounding"),
  );
  return [
    `The draft failed final-output verification: ${acceptance.missing.join(", ")}.`,
    "Revise it before it can be shown to the user.",
    citationMissing || requirePassageIds
      ? requirePassageIds
        ? "Cite exact source-scoped passage identifiers already present in the evidence context (source:<id>:passage:<start>-<end>). Every material claim must include at least one persisted passage id. Do not invent identifiers or rely on bare URLs alone."
        : "Cite the bound source URL or exact source-scoped passage identifiers already present in the evidence context. Ground each material claim to a persisted passage id."
      : "",
    acceptedPassageIds.length > 0 &&
    (requirePassageIds ||
      acceptance.missing.some((item) =>
        item.startsWith("passage_citation_coverage:"),
      ) ||
      acceptance.missing.some((item) => item.startsWith("verifier:citation_coverage:")))
      ? `The complete accepted passage-id set is: ${acceptedPassageIds.join(", ")}. Use each applicable identifier exactly as written, on the same sentence as the claim it supports; when multiple fetched sources require coverage, cite every listed source at least once.`
      : "",
    missingPassageIds.length > 0
      ? `Your rejected draft specifically omitted coverage for: ${missingPassageIds.join(", ")}. Preserve the supported draft content and add each omitted identifier to the exact material claim sentence supported by that passage.`
      : "",
    acceptance.missing.some((item) => item.includes("open_evidence_conflicts"))
      ? "Include an explicit ## Limitations section that says the sources conflict, contradict, disagree, or differ. Do not imply that the disagreement was resolved when the evidence remains contradictory."
      : "",
    acceptance.missing.includes("limitations_section")
      ? "Include an explicit Limitations section."
      : "",
    acceptance.missing.includes("confidence_section")
      ? "Include an explicit Confidence section."
      : "",
    finalRelevanceMissing && requiredLiteralAnchors.length > 0
      ? `Preserve every exact user-required literal marker in the final answer: ${requiredLiteralAnchors.join(", ")}. Copy each marker character-for-character.`
      : "",
    finalRelevanceMissing
      ? "Directly answer the original mission subject; do not substitute an adjacent topic or return process commentary."
      : "",
    acceptance.missing.some((item) =>
      item.includes("claim_grounding:missing_quote") ||
      item.includes("claim_grounding:quote_"),
    )
      ? "For explicitly requested quotation work, include at least one direct quote copied character-for-character from the cited passage. Every other quoted span must also appear verbatim in its cited passage; remove or paraphrase unsupported quotation marks. Paraphrased material claims still need persisted passage ids."
      : "",
    "Return only the corrected final answer. Do not request tools or repeat this instruction.",
    `Rejected draft for revision:\n${truncateForTrace(rejectedCandidate, 6000)}`,
  ].filter(Boolean).join("\n\n");
}

function getMissionLedgerStatusForStopReason(
  stopReason: AgentRunStopReason,
): MissionLedgerStatus {
  switch (stopReason) {
    case "write_completed":
    case "final":
    case "clarifying_question":
      return "complete";
    case "budget":
      return "budget";
    case "user_stopped":
      return "stopped";
    case "error":
    default:
      return "blocked";
  }
}

function isRunStopRequested(abortSignal: AbortSignal | undefined): boolean {
  return abortSignal?.aborted ?? false;
}

/**
 * Nested executors receive a host-linked signal rather than the coordinator's
 * original controller. Preserve a budget terminal when that host signal
 * carries an explicit deadline reason; a literal user stop remains distinct.
 */
function isDeadlineAbortSignal(signal: AbortSignal | undefined): boolean {
  if (!signal?.aborted) return false;
  const reason = signal.reason;
  const message =
    reason instanceof Error
      ? reason.message
      : typeof reason === "string"
        ? reason
        : "";
  return /(?:wall[-\s]?clock|deadline|time(?:out)?|budget)[\s\S]{0,80}(?:expired|exhausted|reached)|(?:expired|exhausted|reached)[\s\S]{0,80}(?:wall[-\s]?clock|deadline|time(?:out)?|budget)/iu.test(
    message,
  );
}

async function checkpointRunIfDue({
  toolContext,
  events,
  runId,
  step,
  stepLimit,
  runPlan,
  toolNames,
  status = "running",
  message,
  force = false,
}: {
  toolContext: ToolExecutionContext;
  events: AgentRunEvents;
  runId: string;
  step: number;
  stepLimit: number;
  runPlan: RunPlan;
  toolNames: string[];
  status?: string;
  message?: string;
  force?: boolean;
}) {
  if (
    step <= 0 ||
    (!force && step % CHECKPOINT_EVERY_STEPS !== 0) ||
    stepLimit < CHECKPOINT_EVERY_STEPS ||
    !hasCheckpointVaultApi(toolContext)
  ) {
    return;
  }

  try {
    const result = await appendAgentRunCheckpoint(toolContext, {
      runId,
      step,
      maxSteps: stepLimit,
      status,
      route: runPlan.route,
      toolNames,
      message: message ?? `Completed planning step ${step}; continuing agent loop.`,
      timestamp: toolContext.now?.() ?? new Date(),
    });
    events.onTrace?.({
      id: `checkpoint-${step}`,
      kind: "status",
      step,
      path: result.path,
      message: `Saved run checkpoint to ${result.path}`,
      outputPreview: result,
    });
  } catch (error) {
    events.onTrace?.({
      id: `checkpoint-${step}:error`,
      kind: "error",
      step,
      message: `Run checkpoint failed: ${getUnknownErrorMessage(error)}`,
      error: {
        code: "checkpoint_failed",
        message: getUnknownErrorMessage(error),
      },
    });
  }
}

function hasCheckpointVaultApi(toolContext: ToolExecutionContext): boolean {
  const vault = (toolContext as Partial<ToolExecutionContext>).app?.vault as
    | Record<string, unknown>
    | undefined;

  return (
    typeof vault?.getFolderByPath === "function" &&
    typeof vault.getFileByPath === "function" &&
    typeof vault.createFolder === "function" &&
    typeof vault.create === "function" &&
    typeof vault.read === "function" &&
    typeof vault.modify === "function"
  );
}

const CACHEABLE_TOOL_NAMES = new Set([
  "read_current_file",
  "inspect_vault_context",
  "list_markdown_files",
  "search_markdown_files",
  "inspect_semantic_index",
  "semantic_search_notes",
  "read_markdown_files",
  "read_file",
  "count_words",
  "web_fetch",
  "get_note_graph_context",
  "find_related_notes",
  "suggest_note_links",
]);

export async function executePreparedToolWithMetrics({
  toolRegistry,
  preparedAction,
  authorization,
  toolContext,
  events,
  step,
}: {
  toolRegistry: ToolRegistry;
  preparedAction: PreparedAction;
  authorization: AuthorizedActionContext;
  toolContext: ToolExecutionContext;
  events: AgentRunEvents;
  step?: number;
}): Promise<ToolExecutionResult> {
  const startedAt = nowMs();
  const inputChars = measureSerializedChars(preparedAction.normalizedArgs);
  if (!toolRegistry.executePrepared) {
    return {
      ok: false,
      toolName: preparedAction.toolName,
      mutationState: "not_applied",
      error: {
        code: "prepared_execution_unavailable",
        message: "The tool registry does not support prepared execution.",
      },
    };
  }
  try {
    const result = await toolRegistry.executePrepared(
      preparedAction,
      toolContext,
      authorization,
    );
    // Sandbox validation is always prepared and approved. Preserve its
    // already-redacted bounded diagnostic on this execution path so transcript
    // compaction cannot remove the evidence required by the next repair turn.
    rememberLatestFastValidationDiagnostic(
      toolContext.runtimeCache,
      preparedAction.toolName,
      result,
    );
    if (result.ok && preparedAction.toolName === "code_workspace_write_expected") {
      forgetVerifiedWorkspaceReadObservation(
        toolContext.runtimeCache,
        getString(preparedAction.normalizedArgs.workspaceId),
        getString(preparedAction.target.path) ??
          getString(preparedAction.normalizedArgs.path),
      );
    }
    if (
      result.ok &&
      preparedAction.toolName === "upsert_mermaid_block" &&
      toolContext.runtimeCache
    ) {
      toolContext.runtimeCache.verifiedMermaidRead = undefined;
    }
    emitMetricEvent(events, {
      kind: "tool",
      name: preparedAction.toolName,
      step,
      durationMs: elapsedMs(startedAt),
      inputChars,
      outputChars: measureSerializedChars(result),
    });
    return result;
  } catch (error) {
    emitMetricEvent(events, {
      kind: "tool",
      name: preparedAction.toolName,
      step,
      durationMs: elapsedMs(startedAt),
      inputChars,
    });
    throw error;
  }
}

function isPreparedActionWithinRunnerScope({
  toolName,
  descriptor,
  action,
  allowedToolNames,
  policyRouted,
  missionIntent,
  writeAutonomy,
}: {
  toolName: string;
  descriptor: ToolDescriptor;
  action: PreparedAction;
  allowedToolNames: Set<string>;
  policyRouted: RoutedMissionIntent;
  missionIntent: MissionIntent;
  writeAutonomy: boolean;
}): boolean {
  if (
    !allowedToolNames.has(toolName) ||
    action.toolName !== toolName ||
    action.target.system !== descriptor.capability.system ||
    action.target.resourceType !== descriptor.capability.resourceType
  ) {
    return false;
  }
  if (descriptor.effect === "read") {
    return true;
  }
  if (descriptor.capability.system === "vault") {
    return (
      policyRouted.writeScope !== "none" ||
      writeAutonomy ||
      missionIntent.explicitMutation ||
      missionIntent.noteOutput
    );
  }
  // External and workspace tools reach this point only after the mission
  // allowlist's explicit integration/code/browser intent gates accepted them.
  return descriptor.capability.system !== "web";
}

async function executeToolWithMetrics({
  toolRegistry,
  toolCall,
  toolContext,
  events,
  step,
}: {
  toolRegistry: ToolRegistry;
  toolCall: { name: string; arguments: Record<string, unknown> };
  toolContext: ToolExecutionContext;
  events: AgentRunEvents;
  step?: number;
}) {
  const startedAt = nowMs();
  const inputChars = measureSerializedChars(toolCall.arguments);
  const toolCache = toolContext.runtimeCache?.toolResults;
  const cacheKey =
    toolCache && CACHEABLE_TOOL_NAMES.has(toolCall.name)
      ? getToolCacheKey(toolCall.name, toolCall.arguments)
      : null;

  if (cacheKey) {
    const cachedResult = toolCache?.get(cacheKey);
    if (cachedResult) {
      rememberTrustedWebFetchResult(
        toolContext.runtimeCache,
        toolCall.name,
        cachedResult,
      );
      emitMetricEvent(events, {
        kind: "tool",
        name: toolCall.name,
        step,
        durationMs: 0,
        cached: true,
        cacheKey,
        savedDurationMs: elapsedMs(startedAt),
        inputChars,
        outputChars: measureSerializedChars(cachedResult),
      });
      return cachedResult;
    }
  }

  try {
    const result = await toolRegistry.execute(toolCall, toolContext);
    rememberTrustedWebFetchResult(
      toolContext.runtimeCache,
      toolCall.name,
      result,
    );
    rememberVerifiedWorkspaceReadResult(
      toolContext.runtimeCache,
      toolCall,
      toolContext,
      result,
    );
    rememberVerifiedMermaidReadResult(
      toolContext.runtimeCache,
      toolCall,
      result,
    );
    rememberLatestFastValidationDiagnostic(
      toolContext.runtimeCache,
      toolCall.name,
      result,
    );
    if (cacheKey && result.ok) {
      toolCache?.set(cacheKey, result);
    }
    emitMetricEvent(events, {
      kind: "tool",
      name: toolCall.name,
      step,
      durationMs: elapsedMs(startedAt),
      inputChars,
      outputChars: measureSerializedChars(result),
    });
    if (result.ok && step === undefined) {
      const receipt = buildReceiptFromToolExecution(
        toolCall.name,
        result,
        toolRegistry.getDescriptor?.(toolCall.name) ?? null,
      );
      if (receipt) {
        const traceStep = step ?? 0;
        events.onTrace?.({
          id: `local:${traceStep}:${toolCall.name}:transaction:validated`,
          kind: "status",
          step: traceStep,
          toolName: toolCall.name,
          message: "Vault transaction validated.",
          outputPreview: truncateTracePayload(result.output),
        });
        events.onTrace?.({
          id: `local:${traceStep}:${toolCall.name}:transaction:applied`,
          kind: "status",
          step: traceStep,
          toolName: toolCall.name,
          message: "Vault transaction applied.",
          outputPreview: truncateTracePayload(result.output),
        });
        events.onReceipt?.(receipt);
        events.onTrace?.({
          id: `local:${traceStep}:${toolCall.name}:transaction:committed`,
          kind: "receipt",
          step: traceStep,
          toolName: toolCall.name,
          operation: receipt.operation,
          path: receipt.path,
          toPath: receipt.toPath,
          backupPath: receipt.backupPath,
          message: "Vault transaction committed.",
          outputPreview: truncateTracePayload(receipt.output ?? receipt),
        });
      }
    }
    return result;
  } catch (error) {
    emitMetricEvent(events, {
      kind: "tool",
      name: toolCall.name,
      step,
      durationMs: elapsedMs(startedAt),
      inputChars,
    });
    throw error;
  }
}

/**
 * Decide whether a tool result should advance the MissionGraph node.
 * Red `code_validate_fast` must advance (sandbox ran; next node records repair).
 * Red targeted/full must not advance toward commit.
 */
function hasFailedCodeValidationStatus(
  toolName: string,
  result: Pick<ToolExecutionResult, "ok" | "output">,
): boolean {
  return (
    /^code_validate_(?:fast|targeted|full)$/u.test(toolName) &&
    result.ok &&
    isRecord(result.output) &&
    (result.output.status === "failed" ||
      (isRecord(result.output.validationReceipt) &&
        result.output.validationReceipt.status === "failed"))
  );
}

/**
 * Classify a tool result for cross-run outcome memory by domain semantics,
 * rather than trusting the transport-level `ok` bit alone.
 *
 * Fast red still advances the MissionGraph to its repair checkpoint, but it is
 * not a successful validation. Likewise, a `repaired` cycle records only that
 * validation remains red; it does not prove a workspace change. Only
 * `outcome: "passed"` is a successful repair checkpoint.
 */
export function resolveToolOutcomeMemoryDispositionV1(
  toolName: string,
  result: Pick<ToolExecutionResult, "ok" | "output" | "error">,
): { ok: boolean; errorCode: string | undefined } {
  if (hasFailedCodeValidationStatus(toolName, result)) {
    return { ok: false, errorCode: "validation_red" };
  }
  if (
    toolName === "code_repair_record_cycle" &&
    result.ok &&
    isRecord(result.output) &&
    result.output.outcome !== "passed"
  ) {
    return { ok: false, errorCode: "repair_still_red" };
  }
  return {
    ok: result.ok,
    errorCode: result.ok ? undefined : result.error?.code,
  };
}

/**
 * A recovery gate is paid only by a canonical, independently read-back
 * workspace receipt whose content hash actually changed. Prepared calls that
 * failed, escaped repository scope, or rewrote byte-identical content cannot
 * masquerade as a correction.
 */
export function receiptProvesWorkspaceContentChangeV1(
  receipt: AgentRunReceipt,
): boolean {
  if (
    (receipt.commitKind !== "committed" &&
      receipt.commitKind !== "reconciled") ||
    receipt.readback?.status !== "verified"
  ) {
    return false;
  }
  const output = isRecord(receipt.output) ? receipt.output : null;
  const mutationReceipt =
    output && isRecord(output.receipt) ? output.receipt : null;
  if (!mutationReceipt || mutationReceipt.version !== 2) return false;
  const beforeSha256 = mutationReceipt.beforeSha256;
  const afterSha256 = mutationReceipt.afterSha256;
  const validHash = (value: unknown): value is string =>
    typeof value === "string" && /^sha256:[a-f0-9]{64}$/u.test(value);
  if (
    !(beforeSha256 === null || validHash(beforeSha256)) ||
    !validHash(afterSha256) ||
    receipt.readback.observedRevision !== afterSha256
  ) {
    return false;
  }
  return beforeSha256 !== afterSha256;
}

export function evaluateValidationRecoveryCorrectionReceiptV1(input: {
  graph: MissionGraphV3;
  diagnostic: CodeValidationDiagnosticObservation | null;
  receipt: AgentRunReceipt;
  durableReceipts?: readonly AgentRunReceipt[];
}): {
  eligible: boolean;
  reason:
    | "verified_content_change"
    | "no_verified_content_change"
    | "receipt_path_unverified"
    | "diagnostic_path_mismatch";
  receiptPath: string | null;
  selectedPaths: string[];
} {
  const selectedPaths = getDiagnosticSelectedWorkspaceCorrectionPaths(
    input.graph,
    input.diagnostic,
    input.durableReceipts ?? [],
  );
  const receiptPath = getCanonicalWorkspaceMutationReceiptPathV1(
    input.receipt,
  );
  if (!receiptProvesWorkspaceContentChangeV1(input.receipt)) {
    return {
      eligible: false,
      reason: "no_verified_content_change",
      receiptPath,
      selectedPaths,
    };
  }
  if (receiptPath === null) {
    return {
      eligible: false,
      reason: "receipt_path_unverified",
      receiptPath,
      selectedPaths,
    };
  }
  const recoveryRequiresExactPath =
    getActiveValidationRecoveryFrontierV1(input.graph)?.status ===
    "awaiting_correction";
  if (
    (recoveryRequiresExactPath && selectedPaths.length === 0) ||
    (selectedPaths.length > 0 && !selectedPaths.includes(receiptPath))
  ) {
    return {
      eligible: false,
      reason: "diagnostic_path_mismatch",
      receiptPath,
      selectedPaths,
    };
  }
  return {
    eligible: true,
    reason: "verified_content_change",
    receiptPath,
    selectedPaths,
  };
}

function getCanonicalWorkspaceMutationReceiptPathV1(
  receipt: AgentRunReceipt,
): string | null {
  const output = isRecord(receipt.output) ? receipt.output : null;
  const mutationReceipt =
    output && isRecord(output.receipt) ? output.receipt : null;
  const candidates = [
    mutationReceipt && typeof mutationReceipt.path === "string"
      ? mutationReceipt.path
      : null,
    typeof receipt.path === "string" ? receipt.path : null,
    typeof receipt.resource?.path === "string" ? receipt.resource.path : null,
  ]
    .filter((value): value is string => Boolean(value?.trim()))
    .map((value) => value.replace(/\\/gu, "/").replace(/^(?:\.\/)+/u, ""));
  const unique = [...new Set(candidates)];
  return unique.length === 1 ? unique[0]! : null;
}

/**
 * Delivery receipts prove external effects, not terminal agreement between the
 * authoritative graph and its verifier projection. Keep a soft terminal
 * resumable until both are complete, even after set-loose delivery is paid.
 */
export function resolveEffectiveTerminalStopReasonV1(input: {
  terminalProjectionsAgree: boolean;
  setLooseDeliveryUnpaid: boolean;
  stopReason: AgentRunStopReason;
  acceptanceStatus: MissionAcceptanceResult["status"];
  graphComplete: boolean;
}): AgentRunStopReason {
  if (!input.terminalProjectionsAgree) {
    return "error";
  }
  if (
    input.setLooseDeliveryUnpaid &&
    input.stopReason !== "user_stopped" &&
    input.stopReason !== "error"
  ) {
    return "budget";
  }
  if (
    (input.stopReason === "final" ||
      input.stopReason === "write_completed") &&
    (input.acceptanceStatus !== "pass" || !input.graphComplete)
  ) {
    return "budget";
  }
  return input.stopReason;
}

export function resolveMissionGraphToolResultOk(
  toolName: string,
  result: Pick<ToolExecutionResult, "ok" | "output" | "error">,
): {
  ok: boolean;
  validationStatusFailed: boolean;
  repairCycleTerminalFailure: boolean;
  repairCycleNotPassed: boolean;
} {
  const repairCycleBlocked =
    toolName === "code_repair_record_cycle" &&
    result.ok &&
    isRecord(result.output) &&
    result.output.outcome === "blocked";
  const repairCycleTerminalError =
    toolName === "code_repair_record_cycle" &&
    !result.ok &&
    [
      "unchanged_failure",
      "repair_checkpoint_terminal",
      "repair_cycles_exhausted",
    ].includes(result.error?.code ?? "");
  const repairCycleTerminalFailure =
    repairCycleBlocked || repairCycleTerminalError;
  // Targeted/full ok with status "failed" must not advance toward commit.
  // Fast red must still advance: the next node is code_repair_record_cycle,
  // which records the red receipt and unlocks bounded correction passes.
  // Blocking red fast after retries left the frontier empty and stranded repair.
  const validationStatusFailed =
    /^code_validate_(?:targeted|full)$/u.test(toolName) &&
    hasFailedCodeValidationStatus(toolName, result);
  // Only a real record-cycle result can pay the durable fast-cycle gate for
  // commit. A green fast validation still needs that receipt-bound checkpoint;
  // outcome "repaired" means another bounded cycle is still required.
  const repairCycleNotPassed =
    toolName === "code_repair_record_cycle" &&
    result.ok &&
    isRecord(result.output) &&
    result.output.outcome !== "passed" &&
    result.output.outcome !== "repaired";
  return {
    ok:
      result.ok &&
      !repairCycleTerminalFailure &&
      !validationStatusFailed &&
      !repairCycleNotPassed,
    validationStatusFailed,
    repairCycleTerminalFailure,
    repairCycleNotPassed,
  };
}

export function isTerminalMissionGraphBlocker(
  node: Pick<
    MissionGraphV3["nodes"][string],
    "status" | "blocker" | "retries"
  >,
): boolean {
  return node.status === "blocked" &&
    (node.blocker?.code === "tool_failure_terminal" ||
      node.blocker?.code === "tool_failure_repeated" ||
      node.retries.attempts >= node.retries.maxAttempts ||
      node.retries.consecutiveFailureCount >= 2);
}

const REQUIRED_CODE_VALIDATION_OR_REPAIR_TOOL_NAMES = new Set([
  "code_validate_fast",
  "code_validate_targeted",
  "code_validate_full",
  "code_repair_record_cycle",
]);

type TerminalMissionGraphNodeView = Pick<
  MissionGraphV3["nodes"][string],
  "id" | "objective" | "status" | "blocker" | "retries" | "allowedTools"
>;

function isRequiredTerminalCodeValidationOrRepairNode(
  node: TerminalMissionGraphNodeView,
): boolean {
  if (
    node.id.startsWith("optional-") ||
    /^optional\b/iu.test(node.objective)
  ) {
    return false;
  }
  return (
    isTerminalMissionGraphBlocker(node) &&
    node.allowedTools.some((toolName) =>
      REQUIRED_CODE_VALIDATION_OR_REPAIR_TOOL_NAMES.has(toolName),
    )
  );
}

/**
 * Required non-optional validation and repair nodes are part of the code proof
 * chain. Once one is terminal, an unpaid code_execution stage cannot be paid by
 * unrelated set-loose reads, mutations, note writes, or GitHub tools.
 */
export function hasUnpaidCodeExecutionTerminalValidationBlocker(
  graph:
    | {
        nodes: Record<string, TerminalMissionGraphNodeView>;
      }
    | null
    | undefined,
  unpaidDeliveryProofs: readonly string[],
): boolean {
  return (
    unpaidDeliveryProofs.includes("code_execution") &&
    Boolean(
      graph &&
        Object.values(graph.nodes).some(
          isRequiredTerminalCodeValidationOrRepairNode,
        ),
    )
  );
}

/**
 * True when a MissionGraph still has a ready/running node that can offer work.
 * Soft companions must not hide terminal blockers when this is false.
 */
export function hasReadyOrRunningMissionGraphUnpaidWork(
  graph:
    | {
        nodes: Record<
          string,
          Pick<MissionGraphV3["nodes"][string], "status">
        >;
      }
    | null
    | undefined,
): boolean {
  if (!graph) return false;
  return Object.entries(graph.nodes).some(
    ([nodeId, node]) =>
      !isOptionalMissionGraphNode(nodeId, node as MissionGraphV3["nodes"][string]) &&
      (node.status === "ready" || node.status === "running"),
  );
}

/**
 * Finish the run when any node is a terminal MissionGraph blocker and no
 * ready/running node still offers unpaid work — even if Soft companions keep
 * the offered tool catalog nonempty.
 */
export function shouldFinishRunForTerminalMissionGraphBlockers(
  graph:
    | {
        nodes: Record<
          string,
          Pick<
            MissionGraphV3["nodes"][string],
            "status" | "blocker" | "retries"
          >
        >;
      }
    | null
    | undefined,
): boolean {
  if (!graph) return false;
  const nodes = Object.entries(graph.nodes).filter(
    ([nodeId, node]) =>
      !isOptionalMissionGraphNode(
        nodeId,
        node as MissionGraphV3["nodes"][string],
      ),
  );
  if (!nodes.some(([, node]) => isTerminalMissionGraphBlocker(node))) {
    return false;
  }
  return !hasReadyOrRunningMissionGraphUnpaidWork(graph);
}

const MAX_VERIFIED_WORKSPACE_READ_OBSERVATIONS = 64;
const MAX_VERIFIED_WORKSPACE_READ_CONTENT_CHARS = 100_000;
const MAX_FAST_VALIDATION_DIAGNOSTIC_CHARS = 6_000;
const FAST_VALIDATION_DIAGNOSTIC_OMISSION =
  "\n[bounded diagnostic middle omitted]\n";

function boundFastValidationDiagnostic(value: string): string {
  if (value.length <= MAX_FAST_VALIDATION_DIAGNOSTIC_CHARS) return value;
  const remaining =
    MAX_FAST_VALIDATION_DIAGNOSTIC_CHARS -
    FAST_VALIDATION_DIAGNOSTIC_OMISSION.length;
  const head = Math.ceil(remaining / 2);
  const tail = Math.floor(remaining / 2);
  return `${value.slice(0, head)}${FAST_VALIDATION_DIAGNOSTIC_OMISSION}${value.slice(-tail)}`;
}

export function rememberLatestFastValidationDiagnostic(
  runtimeCache: AgentRuntimeCache | undefined,
  toolName: string,
  result: ToolExecutionResult,
): void {
  if (
    !isForegroundCodeValidationToolName(toolName) ||
    !runtimeCache ||
    !result.ok
  ) {
    return;
  }
  runtimeCache.latestFastValidationDiagnostic = undefined;
  const output = isRecord(result.output) ? result.output : null;
  if (!output || output.status !== "failed") return;
  const excerpt = isRecord(output.validationDiagnosticExcerpt)
    ? output.validationDiagnosticExcerpt
    : null;
  if (!excerpt) return;
  const rawStdout = typeof excerpt.stdout === "string" ? excerpt.stdout : "";
  const rawStderr = typeof excerpt.stderr === "string" ? excerpt.stderr : "";
  const stdout = rawStdout
    ? boundFastValidationDiagnostic(rawStdout)
    : "";
  const stderr = rawStderr
    ? boundFastValidationDiagnostic(rawStderr)
    : "";
  const redactedLines = typeof excerpt.redactedLines === "number" &&
      Number.isSafeInteger(excerpt.redactedLines) &&
      excerpt.redactedLines >= 0
    ? excerpt.redactedLines
    : 0;
  if (!stdout && !stderr) return;
  runtimeCache.latestFastValidationDiagnostic = {
    stdout,
    stderr,
    truncated:
      excerpt.truncated === true ||
      rawStdout.length > MAX_FAST_VALIDATION_DIAGNOSTIC_CHARS ||
      rawStderr.length > MAX_FAST_VALIDATION_DIAGNOSTIC_CHARS,
    redactedLines,
  };
}

type DurableFastValidationReceipt = Pick<
  AgentRunReceipt,
  | "version"
  | "toolName"
  | "actionId"
  | "payloadFingerprint"
  | "grantId"
  | "commitKind"
  | "readback"
  | "output"
>;

/**
 * Rehydrates only bounded fast/targeted/full validator evidence that was
 * already committed in a canonical action receipt. Receipts are chronological,
 * so a newer successful validation (or a newer receipt without a usable
 * diagnostic) clears an older failure rather than reviving stale repair
 * context after continuation.
 */
export function restoreLatestFastValidationDiagnosticFromReceipts(
  runtimeCache: AgentRuntimeCache | undefined,
  receipts: readonly DurableFastValidationReceipt[],
): void {
  if (!runtimeCache) return;
  for (const receipt of receipts) {
    if (
      receipt.version !== 1 ||
      !isForegroundCodeValidationToolName(receipt.toolName) ||
      !receipt.actionId ||
      !receipt.payloadFingerprint ||
      !receipt.grantId ||
      (receipt.commitKind !== "committed" &&
        receipt.commitKind !== "reconciled") ||
      receipt.readback?.status !== "verified"
    ) {
      continue;
    }
    rememberLatestFastValidationDiagnostic(
      runtimeCache,
      receipt.toolName,
      {
        ok: true,
        toolName: receipt.toolName,
        output: receipt.output,
      },
    );
  }
}

/**
 * Rehydrate set-loose commit Soft-union gating across durable continuations.
 */
export function restorePassedFastRepairCycleFromReceipts(
  runtimeCache: AgentRuntimeCache | undefined,
  receipts: readonly Pick<DurableFastValidationReceipt, "toolName" | "output">[],
): void {
  if (!runtimeCache) return;
  for (const receipt of receipts) {
    const output = isRecord(receipt.output) ? receipt.output : null;
    const passedRepair =
      receipt.toolName === "code_repair_record_cycle" &&
      output?.outcome === "passed";
    if (passedRepair) {
      runtimeCache.passedFastRepairCycle = true;
      return;
    }
  }
}

export function getLatestFastValidationDiagnostic(
  runtimeCache: AgentRuntimeCache | undefined,
): CodeValidationDiagnosticObservation | null {
  const diagnostic = runtimeCache?.latestFastValidationDiagnostic;
  return diagnostic ? { ...diagnostic } : null;
}

function normalizeWorkspaceObservationId(value: string): string {
  return (
    value
      .toLowerCase()
      .replace(/[^a-z0-9._-]+/gu, "-")
      .replace(/^-+|-+$/gu, "")
      .slice(0, 128) || "adhoc"
  );
}

function verifiedWorkspaceReadKey(workspaceId: string, path: string): string {
  return JSON.stringify([workspaceId, path]);
}

export function rememberVerifiedWorkspaceReadResult(
  runtimeCache: AgentRuntimeCache | undefined,
  toolCall: Pick<ModelToolCall, "name" | "arguments">,
  context: Pick<
    ToolExecutionContext,
    "rootMissionId" | "runId" | "operationId"
  >,
  result: ToolExecutionResult,
): void {
  if (
    toolCall.name !== "code_workspace_read" ||
    !runtimeCache ||
    !result.ok ||
    !isRecord(result.output)
  ) {
    return;
  }
  const path = getString(result.output.path);
  const sha256 = getString(result.output.sha256);
  // A zero-byte source file (for example a package marker such as
  // `__init__.py`) is still a complete, independently verified read. Do not
  // route it through getString(), which intentionally treats an empty string
  // as absent for identifiers and other required scalar fields.
  const content =
    typeof result.output.content === "string"
      ? result.output.content
      : undefined;
  if (
    !path ||
    !sha256 ||
    !/^sha256:[a-f0-9]{64}$/u.test(sha256) ||
    content === undefined ||
    content.length > MAX_VERIFIED_WORKSPACE_READ_CONTENT_CHARS
  ) {
    return;
  }
  const workspaceId = normalizeWorkspaceObservationId(
    getString(toolCall.arguments.workspaceId) ??
      context.rootMissionId ??
      context.runId ??
      context.operationId ??
      "adhoc",
  );
  runtimeCache.verifiedWorkspaceReads ??= new Map();
  const key = verifiedWorkspaceReadKey(workspaceId, path);
  if (
    !runtimeCache.verifiedWorkspaceReads.has(key) &&
    runtimeCache.verifiedWorkspaceReads.size >=
      MAX_VERIFIED_WORKSPACE_READ_OBSERVATIONS
  ) {
    const oldestKey = runtimeCache.verifiedWorkspaceReads.keys().next().value;
    if (typeof oldestKey === "string") {
      runtimeCache.verifiedWorkspaceReads.delete(oldestKey);
    }
  }
  runtimeCache.verifiedWorkspaceReads.set(key, {
    workspaceId,
    path,
    sha256,
    content,
  });
}

function rememberVerifiedMermaidReadResult(
  runtimeCache: AgentRuntimeCache | undefined,
  toolCall: Pick<ModelToolCall, "name">,
  result: ToolExecutionResult,
): void {
  if (!runtimeCache || !result.ok) return;
  if (toolCall.name === "upsert_mermaid_block") {
    runtimeCache.verifiedMermaidRead = undefined;
    return;
  }
  if (toolCall.name !== "read_mermaid_block" || !isRecord(result.output)) {
    return;
  }
  const path = getString(result.output.path);
  const sha256 = getString(result.output.sha256);
  const selector = result.output.selector;
  if (
    !path ||
    !sha256 ||
    !/^sha256:[a-f0-9]{64}$/u.test(sha256) ||
    !isRecord(selector)
  ) {
    return;
  }
  runtimeCache.verifiedMermaidRead = {
    path,
    sha256,
    selector: { ...selector },
  };
}

export function getVerifiedWorkspaceReadObservation(
  runtimeCache: AgentRuntimeCache | undefined,
  path: string,
  workspaceId?: string,
): VerifiedWorkspaceReadObservation | null {
  const observations = runtimeCache?.verifiedWorkspaceReads;
  if (!observations) return null;
  if (workspaceId) {
    return (
      observations.get(
        verifiedWorkspaceReadKey(
          normalizeWorkspaceObservationId(workspaceId),
          path,
        ),
      ) ?? null
    );
  }
  const matches = [...observations.values()].filter(
    (observation) => observation.path === path,
  );
  return matches.length === 1 ? matches[0]! : null;
}

/**
 * Resolve a corrective write only against the single durable workspace that
 * the host independently verified. Earlier model-authored reads may omit or
 * vary the workspace label, so a path-only lookup can become ambiguous after
 * the host refreshes sibling files during a multi-file repair.
 */
export function getVerifiedWorkspaceWriteObservation(
  runtimeCache: AgentRuntimeCache | undefined,
  path: string,
  durableReceipts: readonly AgentRunReceipt[],
): VerifiedWorkspaceReadObservation | null {
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  return workspaceId
    ? getVerifiedWorkspaceReadObservation(runtimeCache, path, workspaceId)
    : null;
}

/**
 * A single explicit web_fetch target is a user-owned read boundary. Bind the
 * provider call back to that URL, and preserve an explicit refresh=true/false
 * directive, so a model cannot silently substitute a sibling domain or bypass
 * the user's cache choice.
 */
export function bindExplicitWebFetchContract(
  prompt: string,
  toolCall: ModelToolCall,
): ModelToolCall | null {
  if (
    toolCall.name !== "web_fetch" ||
    !/\bweb_fetch\b/iu.test(prompt)
  ) {
    return null;
  }
  const urls = new Set<string>();
  for (const match of prompt.matchAll(/https?:\/\/[^\s<>"'`]+/giu)) {
    const candidate = match[0]!.replace(/[)\],.;!?]+$/gu, "");
    if (!candidate) continue;
    try {
      const parsed = new URL(candidate);
      if (parsed.protocol === "http:" || parsed.protocol === "https:") {
        parsed.hash = "";
        urls.add(parsed.toString());
      }
    } catch {
      // Invalid prompt URLs remain model text; do not create a host binding.
    }
  }
  if (urls.size !== 1) return null;

  const refreshMatch = /\brefresh\s*=\s*(true|false)\b/iu.exec(prompt);
  const explicitUrl = [...urls][0]!;
  return {
    ...toolCall,
    arguments: {
      ...toolCall.arguments,
      url: explicitUrl,
      ...(refreshMatch
        ? { refresh: refreshMatch[1]!.toLowerCase() === "true" }
        : {}),
    },
  };
}

export function attachMissingRequiredLiteralAnchors(
  content: string,
  prompt: string,
): { content: string; insertedAnchors: string[] } {
  const normalizedContent = content.toLowerCase();
  const insertedAnchors = extractRequiredLiteralAnchors(prompt).filter(
    (anchor) => !normalizedContent.includes(anchor.toLowerCase()),
  );
  if (insertedAnchors.length === 0) {
    return { content, insertedAnchors: [] };
  }
  const separator = content.endsWith("\n") ? "\n" : "\n\n";
  return {
    content: `${content}${separator}${insertedAnchors.join("\n")}`,
    insertedAnchors,
  };
}

export function bindVerifiedWorkspaceRead(
  toolCall: ModelToolCall,
  exactPath: string,
  durableReceipts: readonly AgentRunReceipt[],
): ModelToolCall | null {
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  if (toolCall.name !== "code_workspace_read" || !workspaceId || !exactPath) {
    return null;
  }
  return {
    ...toolCall,
    arguments: {
      ...toolCall.arguments,
      workspaceId,
      path: exactPath,
    },
  };
}

function escapeRepositoryProfileKeyRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}

/**
 * When the mission names exactly one trusted repository profile key, return it.
 * Zero or multiple named trusted keys fail closed (no host broaden).
 */
export function resolveSingleNamedTrustedRepositoryProfileKey(
  prompt: string,
  trustedProfileKeys: readonly string[],
): string | null {
  if (!prompt.trim() || trustedProfileKeys.length === 0) return null;
  const uniqueTrusted = [
    ...new Set(
      trustedProfileKeys
        .map((key) => (typeof key === "string" ? key.trim() : ""))
        .filter((key) => /^[a-z0-9][a-z0-9._-]*$/u.test(key)),
    ),
  ].sort((left, right) => right.length - left.length || left.localeCompare(right));
  const named = new Set<string>();
  for (const key of uniqueTrusted) {
    const pattern = new RegExp(
      `(^|[^a-z0-9._-])${escapeRepositoryProfileKeyRegExp(key)}(?![a-z0-9._-])`,
      "u",
    );
    if (pattern.test(prompt)) {
      named.add(key);
    }
  }
  if (named.size !== 1) return null;
  return [...named][0]!;
}

/**
 * Host-bind `code_workspace_create` onto verified repository authority from an
 * independently read Linear contract, or the single trusted profile explicitly
 * named in an ordinary repository mission, so create cannot silently fall
 * through to scratch.
 * Preserves a model-provided workspaceId; otherwise leaves fallback to the
 * workspace tool's existing owner/run derivation.
 */
export function bindTrustedRepositoryWorkspaceCreate(
  toolCall: ModelToolCall,
  prompt: string,
  trustedProfileKeys: readonly string[],
  verifiedRepositoryProfileKey?: string | null,
): ModelToolCall | null {
  if (toolCall.name !== "code_workspace_create") return null;
  const repositoryProfileKey =
    verifiedRepositoryProfileKey &&
    trustedProfileKeys.includes(verifiedRepositoryProfileKey)
      ? verifiedRepositoryProfileKey
      : resolveSingleNamedTrustedRepositoryProfileKey(
          prompt,
          trustedProfileKeys,
        );
  if (!repositoryProfileKey) return null;
  const workspaceId =
    typeof toolCall.arguments.workspaceId === "string" &&
    toolCall.arguments.workspaceId.trim()
      ? toolCall.arguments.workspaceId
      : null;
  return {
    ...toolCall,
    arguments: {
      ...(workspaceId ? { workspaceId } : {}),
      kind: "repository",
      repositoryProfileKey,
    },
  };
}

const VERIFIED_WORKSPACE_LIFECYCLE_TOOL_NAMES = new Set([
  "code_validate_fast",
  "code_validate_targeted",
  "code_validate_full",
  "code_repair_status",
  "code_repair_record_cycle",
  "code_commit_verified",
]);

const VERIFIED_WORKSPACE_OBSERVATION_TOOL_NAMES = new Set([
  "code_workspace_status",
  "code_workspace_stat",
  "code_workspace_list",
  "code_workspace_read",
  "code_workspace_search",
  "read_workspace_file",
  "list_workspace_files",
  "preview_workspace_html",
]);

/**
 * Every consumer after code_workspace_create operates on one host-verified
 * durable workspace. The model may choose a prompt-scoped relative path, but
 * it may never select or transcribe a different workspace identity.
 */
const VERIFIED_DURABLE_WORKSPACE_CONSUMER_TOOL_NAMES = new Set([
  ...VERIFIED_WORKSPACE_LIFECYCLE_TOOL_NAMES,
  ...VERIFIED_WORKSPACE_OBSERVATION_TOOL_NAMES,
  "code_workspace_mkdir",
  "code_workspace_create_file",
  "code_workspace_export_directory",
  "code_workspace_append",
  "code_workspace_write_expected",
  "code_workspace_patch",
  "code_workspace_move",
  "code_workspace_copy",
  "code_workspace_trash",
  "code_workspace_restore",
  "write_workspace_file",
  "replace_workspace_text",
  "export_workspace_artifact",
]);

/**
 * Project the single verified create-receipt identity into every downstream
 * provider-visible workspace schema, including multi-tool set-loose frontiers.
 * This is a usability constraint only; execution repeats the same host bind.
 */
export function bindVerifiedWorkspaceIdentityToolSchemas(
  tools: readonly ModelToolDefinition[],
  durableReceipts: readonly AgentRunReceipt[],
): ModelToolDefinition[] {
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  if (!workspaceId) return [...tools];
  return tools.map((tool) => {
    if (
      !VERIFIED_DURABLE_WORKSPACE_CONSUMER_TOOL_NAMES.has(
        tool.function.name,
      )
    ) {
      return tool;
    }
    const parameters = tool.function.parameters;
    const existingWorkspaceId = parameters.properties?.workspaceId ?? {};
    return {
      ...tool,
      function: {
        ...tool.function,
        parameters: {
          ...parameters,
          properties: {
            ...(parameters.properties ?? {}),
            workspaceId: {
              ...existingWorkspaceId,
              type: "string",
              enum: [workspaceId],
              description:
                "Exact opaque workspace identity from the host-verified durable creation receipt.",
            },
          },
          required: [
            ...new Set([...(parameters.required ?? []), "workspaceId"]),
          ],
        },
      },
    };
  });
}

/**
 * Rebind every downstream workspace consumer at the execution boundary. This
 * prevents an omitted, stale, or model-invented alias from reaching the
 * workspace manager even when a provider ignores the schema enum.
 */
export function bindVerifiedWorkspaceIdentityToolCall(
  toolCall: ModelToolCall,
  durableReceipts: readonly AgentRunReceipt[],
): ModelToolCall | null {
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  if (
    !workspaceId ||
    !VERIFIED_DURABLE_WORKSPACE_CONSUMER_TOOL_NAMES.has(toolCall.name)
  ) {
    return null;
  }
  return {
    ...toolCall,
    arguments: {
      ...toolCall.arguments,
      workspaceId,
    },
  };
}

const HOST_DRIVEN_EXACT_CODE_VALIDATION_TOOL_NAMES = new Set([
  "code_validate_fast",
  "code_validate_targeted",
  "code_validate_full",
]);

/**
 * Exact validation nodes have no model-authored command or destination: the
 * RepositoryProfile/scratch profile, workspace, command, staging manifest,
 * and artifacts are all rebound by the host. If a model twice refuses the
 * only ready validation schema, the host may request that one graph-bound
 * action with a deterministic per-run receipt scope. Approval and prepared
 * action policy remain unchanged.
 */
export function buildExactCodeValidationFallbackToolCall(
  readyToolNames: readonly string[],
  runId: string,
): ModelToolCall | null {
  if (
    readyToolNames.length !== 1 ||
    !HOST_DRIVEN_EXACT_CODE_VALIDATION_TOOL_NAMES.has(readyToolNames[0] ?? "")
  ) {
    return null;
  }
  const repairRequestId = codeRepairRequestIdForRun(runId);
  if (!repairRequestId) {
    return null;
  }
  return {
    name: readyToolNames[0]!,
    arguments: {
      repairRequestId,
      expectedArtifacts: [],
      environment: {},
    },
  };
}

/**
 * A known-folder delivery must export the verified workspace tree, not a
 * model-selected file or workspace transcription. Bind the one foreground
 * destination named by the user and use a run-scoped absent directory so the
 * export remains exact, approval-gated, and non-overwriting.
 */
/** Request verbs, articles, and pronouns carry no meaning in a folder name. */
const DELIVERABLE_LABEL_STOPWORDS_V1 = new Set([
  "a",
  "an",
  "the",
  "my",
  "your",
  "our",
  "me",
  "it",
  "this",
  "that",
  "some",
  "new",
  "please",
  "just",
  "can",
  "could",
  "would",
  "you",
  "write",
  "create",
  "make",
  "build",
  "generate",
  "save",
  "add",
  "implement",
  "develop",
  "and",
  "of",
  "for",
  "in",
  "on",
  "to",
  "with",
  "using",
]);

/** Nouns that name the artifact itself. "cli" is a descriptor, not an artifact. */
const DELIVERABLE_ARTIFACT_NOUNS_V1 =
  /\b(game|app|application|script|tool|program|solver|organizer|library|package|module)\b/gu;

/**
 * A readable folder name for a delivered code artifact, derived from what the
 * user asked for. Previously only the number-guessing e2e prompt got a real
 * name and every other request landed on the Desktop as
 * `code-deliverable-<hex>`, which tells the user nothing about what it is.
 *
 * The result becomes a filesystem path segment, so it is strictly bounded and
 * sanitized to lowercase `[a-z0-9-]` here rather than trusting prompt text.
 */
export function deliverableLabelFromPromptV1(prompt: string): string {
  const fallback = "code-deliverable";
  const text = String(prompt ?? "").toLowerCase();
  // Take the LAST artifact noun: "a cli checkers game" names a game, not a cli.
  const matches = [...text.matchAll(DELIVERABLE_ARTIFACT_NOUNS_V1)];
  const artifact = matches[matches.length - 1];
  if (!artifact || artifact.index === undefined) return fallback;
  const noun = artifact[1]!;
  const preceding = text
    .slice(0, artifact.index)
    .split(/[^a-z0-9]+/u)
    .filter(
      (word) =>
        word.length > 0 &&
        word.length <= 20 &&
        !DELIVERABLE_LABEL_STOPWORDS_V1.has(word),
    )
    .slice(-3);
  const label = [...preceding, noun]
    .join("-")
    .replace(/[^a-z0-9]+/gu, "-")
    .replace(/^-+|-+$/gu, "")
    .slice(0, 48)
    .replace(/-+$/u, "");
  // A label of only the bare noun ("game") is no better than the fallback.
  return label.length > noun.length ? label : fallback;
}

/** The same label as ordinary prose, for a human-facing sentence. */
export function deliverableTitleFromPromptV1(prompt: string): string | null {
  const label = deliverableLabelFromPromptV1(prompt);
  return label === "code-deliverable" ? null : label.replace(/-/gu, " ");
}

export function bindVerifiedWorkspaceDirectoryExport(
  toolCall: ModelToolCall,
  prompt: string,
  runId: string,
  durableReceipts: readonly AgentRunReceipt[],
): ModelToolCall | null {
  if (toolCall.name !== "code_workspace_export_directory") return null;
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  if (!workspaceId || !hasKnownHostDirectoryExportIntent(prompt)) return null;

  const destinationRoots = new Set<"desktop" | "documents" | "downloads">();
  if (/\bdesktop\b/iu.test(prompt)) destinationRoots.add("desktop");
  if (/\bdocuments?(?:\s+folder)?\b/iu.test(prompt)) {
    destinationRoots.add("documents");
  }
  if (/\bdownloads?(?:\s+folder)?\b/iu.test(prompt)) {
    destinationRoots.add("downloads");
  }
  if (destinationRoots.size !== 1) return null;

  const normalizedRunId = runId
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/gu, "");
  const runSuffix = normalizedRunId.slice(-12) || "deliverable";
  const deliverableLabel = deliverableLabelFromPromptV1(prompt);
  return {
    ...toolCall,
    arguments: {
      ...toolCall.arguments,
      workspaceId,
      sourcePath: "",
      destinationRoot: [...destinationRoots][0]!,
      destinationPath: `${deliverableLabel}-${runSuffix}`,
    },
  };
}

/**
 * A receipt-backed host export already owns the terminal delivery projection.
 * Asking the provider for an empty-turn streaming rewrite adds latency and can
 * strand an otherwise completed mission, while its prose is discarded anyway.
 */
export function shouldRequestStreamingFinalProjection(input: {
  enableStreaming: boolean;
  hasDirectFinalContent: boolean;
  verifiedHostExportFinalAnswer: string | null;
}): boolean {
  return (
    input.enableStreaming &&
    !input.hasDirectFinalContent &&
    input.verifiedHostExportFinalAnswer === null
  );
}

/**
 * A receipt-backed answer can itself pay the graph's terminal projection debt.
 * This is intentionally narrow: tool, write, web, and lifecycle proof never
 * qualify here and remain mandatory before finalization.
 */
export function missionAcceptanceHasOnlyFinalProjectionDebt(
  acceptance: Pick<MissionAcceptanceResult, "missing">,
): boolean {
  return (
    acceptance.missing.length > 0 &&
    acceptance.missing.every(
      (item) =>
        item === "final_output" ||
        /(?:^|:)final_relevance$/u.test(item) ||
        /(?:^|:)final_output$/u.test(item),
    )
  );
}

/**
 * A verified host-directory export is already a complete, receipt-backed
 * terminal answer. Once acceptance passes and every explicit proof debt is
 * paid, a controller routing label cannot add authority; another provider turn
 * can only add latency or strand the completed run behind model prose that
 * will be replaced.
 */
export function shouldFinalizeVerifiedHostExportAfterToolUse(input: {
  verifiedHostExportFinalAnswer: string | null;
  acceptanceStatus: MissionAcceptanceResult["status"];
  onlyFinalProjectionProofMissing: boolean;
  pendingRequiredWriteCount: number;
  missingRequiredWebToolCount: number;
  hasPendingOperationGoals: boolean;
  pendingStreamingWriteback: boolean;
  setLooseDeliveryStillUnpaid: boolean;
}): boolean {
  return (
    input.verifiedHostExportFinalAnswer !== null &&
    input.verifiedHostExportFinalAnswer.trim().length > 0 &&
    (input.acceptanceStatus === "pass" ||
      input.onlyFinalProjectionProofMissing) &&
    input.pendingRequiredWriteCount === 0 &&
    input.missingRequiredWebToolCount === 0 &&
    !input.hasPendingOperationGoals &&
    !input.pendingStreamingWriteback &&
    !input.setLooseDeliveryStillUnpaid
  );
}

/**
 * The model may summarize an export, but only the verified host-directory
 * receipt can name where the files landed. Project that receipt into the
 * visible completion message so a plausible but false Desktop path is never
 * shown after a successful delivery.
 */
export function buildVerifiedHostExportFinalAnswer(
  prompt: string,
  durableReceipts: readonly AgentRunReceipt[],
  successfulToolNames: readonly string[],
): string | null {
  const verifiedExportReceipts = durableReceipts.filter(
    (receipt) =>
      receipt.toolName === "code_workspace_export_directory" &&
      receipt.operation === "create" &&
      receipt.readback?.status === "verified",
  );
  if (verifiedExportReceipts.length === 0) return null;
  const exportPaths = new Set(
    verifiedExportReceipts
      .flatMap((receipt) => {
        const output = isRecord(receipt.output) ? receipt.output : null;
        return [
          receipt.resource?.path?.trim() ?? "",
          receipt.path?.trim() ?? "",
          getString(output?.destinationPath)?.trim() ?? "",
        ];
      })
      .filter(
        (exportPath) =>
          /^(?:[A-Za-z]:[\\/]|\/)/u.test(exportPath),
      ),
  );
  if (exportPaths.size !== 1) {
    return [
      "## Delivery completed, but the export path needs review",
      "",
      "The host recorded a verified directory-export receipt, but it could not project one unambiguous absolute path into Chat.",
      "",
      "Open Run Details and use the verified export receipt path; do not rely on a path written by the model.",
    ].join("\n");
  }
  const exportPath = [...exportPaths][0]!;
  const createdPaths = durableReceipts
    .filter(
      (receipt) =>
        receipt.toolName === "code_workspace_create_file" &&
        (receipt.commitKind === "committed" ||
          receipt.commitKind === "reconciled") &&
        receipt.readback?.status === "verified",
    )
    .flatMap((receipt) => {
      const output = isRecord(receipt.output) ? receipt.output : null;
      return [
        receipt.resource?.path?.trim() ?? "",
        receipt.path?.trim() ?? "",
        getString(output?.path)?.trim() ?? "",
      ];
    })
    .filter((createdPath) => createdPath.length > 0);
  const pythonEntryPoint =
    createdPaths.find((createdPath) => /(?:^|\/)main\.py$/iu.test(createdPath)) ??
    createdPaths.find((createdPath) => /\.py$/iu.test(createdPath)) ??
    null;
  const completedValidations = [
    ["code_validate_fast", "fast"],
    ["code_validate_targeted", "targeted"],
    ["code_validate_full", "full"],
  ]
    .filter(([toolName]) => successfulToolNames.includes(toolName!))
    .map(([, label]) => label!);
  // Name what was actually built. This used to read "Python number guessing
  // game" only for that exact e2e prompt and "Code delivered" for everything
  // else, so a delivered checkers game announced itself anonymously.
  const deliverableTitle = deliverableTitleFromPromptV1(prompt);
  const lines = [
    deliverableTitle
      ? `## Done — ${deliverableTitle} delivered`
      : "## Done — Code delivered",
    "",
    deliverableTitle
      ? `I created the requested ${deliverableTitle} and delivered the verified workspace to the requested folder.`
      : "I created the requested code deliverable and delivered the verified workspace to the requested folder.",
    "",
    `- Verified export path: \`${exportPath}\``,
    pythonEntryPoint ? `- Entry point: \`${pythonEntryPoint}\`` : "",
    completedValidations.length > 0
      ? `- Sandbox validation passed: ${completedValidations.join(", ")}`
      : "",
    "",
    pythonEntryPoint
      ? `Run it from the exported directory with \`python ${pythonEntryPoint}\`.`
      : "Open the verified export path above to use the delivered files.",
  ];
  return lines.filter((line, index) => line || lines[index - 1] !== "").join("\n");
}

/**
 * Validate/repair/commit must target the independently verified durable
 * workspace from create receipts and one host-derived request id for the root
 * run. Models often reuse a prompt label or vary requestId/repairRequestId
 * across calls; those values are transcription hints, never authority.
 */
export function bindVerifiedWorkspaceLifecycleTool(
  toolCall: ModelToolCall,
  durableReceipts: readonly AgentRunReceipt[],
  rootRunId: string,
): ModelToolCall | null {
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  const repairRequestId = codeRepairRequestIdForRun(rootRunId);
  if (
    !VERIFIED_WORKSPACE_LIFECYCLE_TOOL_NAMES.has(toolCall.name) ||
    !workspaceId ||
    !repairRequestId
  ) {
    return null;
  }
  const {
    requestId: _modelRequestId,
    repairRequestId: _modelRepairRequestId,
    ...modelArguments
  } = toolCall.arguments;
  const requestBinding = HOST_DRIVEN_EXACT_CODE_VALIDATION_TOOL_NAMES.has(
    toolCall.name,
  )
    ? { repairRequestId }
    : { requestId: repairRequestId };
  return {
    ...toolCall,
    arguments: {
      ...modelArguments,
      workspaceId,
      ...requestBinding,
    },
  };
}

/**
 * Once workspace creation has a single verified durable receipt, read-only
 * workspace observations must inspect that workspace. Model-authored
 * workspace IDs are transcription hints and can become stale across
 * continuation segments or after a provider retries an earlier call.
 */
export function bindVerifiedWorkspaceObservationTool(
  toolCall: ModelToolCall,
  durableReceipts: readonly AgentRunReceipt[],
): ModelToolCall | null {
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  if (
    !VERIFIED_WORKSPACE_OBSERVATION_TOOL_NAMES.has(toolCall.name) ||
    !workspaceId
  ) {
    return null;
  }
  return {
    ...toolCall,
    arguments: {
      ...toolCall.arguments,
      workspaceId,
    },
  };
}

function codeRepairRequestIdForRun(runId: string): string | null {
  const normalizedRunId = runId
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/gu, "-")
    .replace(/^-+|-+$/gu, "");
  return normalizedRunId
    ? `repair-${normalizedRunId}`.slice(0, 128)
    : null;
}

/**
 * Empty or explicit placeholder bodies may be rebound onto the ready graph
 * path. Non-empty content for a different path must fail closed so foreign
 * file bodies are never written onto the current selector.
 */
export function isWorkspaceCreateFilePlaceholderContent(
  content: unknown,
): boolean {
  if (content === undefined || content === null) return true;
  if (typeof content !== "string") return false;
  const trimmed = content.trim();
  if (trimmed.length === 0) return true;
  return /^#\s*placeholder\b/i.test(trimmed);
}

export function bindVerifiedWorkspaceCreateFile(
  toolCall: ModelToolCall,
  graphPath: string | null,
  durableReceipts: readonly AgentRunReceipt[],
): ModelToolCall | null {
  const workspaceId = getSingleVerifiedDurableWorkspaceId(durableReceipts);
  if (
    toolCall.name !== "code_workspace_create_file" ||
    !workspaceId
  ) {
    return null;
  }
  const exactPath =
    graphPath && !graphPath.startsWith("prompt-scoped-")
      ? graphPath
      : null;
  const requestedPath =
    typeof toolCall.arguments.path === "string"
      ? toolCall.arguments.path.trim()
      : "";
  if (
    exactPath &&
    requestedPath &&
    requestedPath !== exactPath &&
    !isWorkspaceCreateFilePlaceholderContent(toolCall.arguments.content)
  ) {
    // Fail closed: do not rewrite path while keeping foreign non-placeholder content.
    return null;
  }
  const boundPath = exactPath ?? requestedPath;
  if (!boundPath) return null;
  return {
    ...toolCall,
    arguments: {
      ...toolCall.arguments,
      workspaceId,
      path: boundPath,
    },
  };
}

/** Near-miss hints when the model invents vault/script names off the code ladder. */
export function describeOffFrontierToolNearMiss(
  toolName: string,
  readyFrontierToolNames: readonly string[] = [],
): string | null {
  return describeOffFrontierToolNearMissImpl(
    toolName,
    readyFrontierToolNames,
  );
}

export function buildOffFrontierToolRejectionMessage(input: {
  toolName: string;
  pendingGraphNodeId?: string | null;
  readyFrontierToolNames: readonly string[];
  preferredNextTool?: string | null;
  category?: string | null;
}): string {
  return buildOffFrontierToolRejectionMessageImpl(input);
}

export function bindVerifiedWorkspaceWriteExpected(
  toolCall: ModelToolCall,
  exactPath: string,
  observation: VerifiedWorkspaceReadObservation,
  exactContent?: string | null,
): ModelToolCall | null {
  if (
    toolCall.name !== "code_workspace_write_expected" ||
    observation.path !== exactPath ||
    !/^sha256:[a-f0-9]{64}$/u.test(observation.sha256)
  ) {
    return null;
  }
  const content =
    typeof exactContent === "string" && exactContent.length > 0
      ? exactContent
      : toolCall.arguments.lineReplacements !== undefined
        ? applyExactWorkspaceLineRangeCorrections(
            observation.content,
            toolCall.arguments.lineReplacements,
          )
        : toolCall.arguments.replacements !== undefined
          ? applyExactWorkspaceCorrectionReplacements(
              observation.content,
              toolCall.arguments.replacements,
            )
          : typeof toolCall.arguments.content === "string"
            ? toolCall.arguments.content
            : null;
  if (content === null) return null;
  return {
    ...toolCall,
    arguments: {
      workspaceId: observation.workspaceId,
      path: exactPath,
      content,
      expectedSha256: observation.sha256,
    },
  };
}

/**
 * When the mission names exactly one FLOW_REAL_* marker and asks for
 * write_expected on src/flow_real.ts, host-provide the exact one-line body.
 */
export function resolvePromptExactFlowRealWriteContent(
  prompt: string,
  exactPath: string,
): string | null {
  if (exactPath !== "src/flow_real.ts") return null;
  const markers = [
    ...prompt.matchAll(/\bFLOW_REAL_[A-Za-z0-9_]+\b/gu),
  ].map((match) => match[0]);
  const unique = [...new Set(markers)];
  if (unique.length !== 1) return null;
  if (
    !/\bcode_workspace_write_expected\b/iu.test(prompt) &&
    !/\bexport\s+const\s+marker\s*=/iu.test(prompt)
  ) {
    return null;
  }
  return `export const marker = "${unique[0]}";\n`;
}

export function applyExactWorkspaceCorrectionReplacements(
  currentContent: string,
  value: unknown,
): string | null {
  if (!Array.isArray(value) || value.length < 1 || value.length > 12) {
    return null;
  }
  let next = currentContent;
  for (const entry of value) {
    if (!isRecord(entry)) return null;
    if (
      Object.keys(entry).some(
        (key) => !["oldText", "newText", "expectedOccurrences"].includes(key),
      ) ||
      typeof entry.oldText !== "string" ||
      entry.oldText.length === 0 ||
      typeof entry.newText !== "string" ||
      (entry.expectedOccurrences !== undefined &&
        (typeof entry.expectedOccurrences !== "number" ||
          !Number.isInteger(entry.expectedOccurrences) ||
          entry.expectedOccurrences < 1 ||
          entry.expectedOccurrences > 12))
    ) {
      return null;
    }
    const expectedOccurrences = typeof entry.expectedOccurrences === "number"
      ? entry.expectedOccurrences
      : 1;
    const parts = next.split(entry.oldText);
    const observedOccurrences = parts.length - 1;
    if (observedOccurrences !== expectedOccurrences) {
      return null;
    }
    next = parts.join(entry.newText);
    if (next.length > MAX_VERIFIED_WORKSPACE_READ_CONTENT_CHARS) return null;
  }
  return next;
}

interface WorkspaceSourceLineRange {
  start: number;
  contentEnd: number;
  separator: string;
}

export function applyExactWorkspaceLineRangeCorrections(
  currentContent: string,
  value: unknown,
): string | null {
  if (!Array.isArray(value) || value.length < 1 || value.length > 12) {
    return null;
  }
  const sourceLines = workspaceSourceLineRanges(currentContent);
  const edits: Array<{
    startLine: number;
    endLine: number;
    start: number;
    end: number;
    replacement: string;
  }> = [];
  let totalSelectedLines = 0;
  let totalReplacementChars = 0;
  for (const entry of value) {
    if (
      !isRecord(entry) ||
      Object.keys(entry).some(
        (key) => !["startLine", "endLine", "newText"].includes(key),
      ) ||
      typeof entry.startLine !== "number" ||
      !Number.isSafeInteger(entry.startLine) ||
      typeof entry.endLine !== "number" ||
      !Number.isSafeInteger(entry.endLine) ||
      typeof entry.newText !== "string" ||
      entry.newText.length === 0 ||
      entry.newText.length > MAX_VERIFIED_WORKSPACE_READ_CONTENT_CHARS ||
      entry.startLine < 1 ||
      entry.endLine < entry.startLine ||
      entry.endLine > sourceLines.length
    ) {
      return null;
    }
    const selectedLineCount = entry.endLine - entry.startLine + 1;
    totalSelectedLines += selectedLineCount;
    totalReplacementChars += entry.newText.length;
    if (
      selectedLineCount > 400 ||
      totalSelectedLines > 600 ||
      totalReplacementChars > MAX_VERIFIED_WORKSPACE_READ_CONTENT_CHARS
    ) return null;
    const firstLine = sourceLines[entry.startLine - 1]!;
    const lastLine = sourceLines[entry.endLine - 1]!;
    const separator = lastLine.separator || preferredWorkspaceLineSeparator(
      sourceLines,
    );
    let replacement = normalizeWorkspaceReplacementLineEndings(
      entry.newText,
      separator || "\n",
    );
    if (lastLine.separator) {
      replacement = `${replacement.replace(/(?:\r\n|\r|\n)$/u, "")}${lastLine.separator}`;
    }
    edits.push({
      startLine: entry.startLine,
      endLine: entry.endLine,
      start: firstLine.start,
      end: lastLine.contentEnd + lastLine.separator.length,
      replacement,
    });
  }
  edits.sort((left, right) => left.startLine - right.startLine);
  for (let index = 1; index < edits.length; index += 1) {
    if (edits[index]!.startLine <= edits[index - 1]!.endLine) return null;
  }
  let next = currentContent;
  for (const edit of [...edits].sort((left, right) => right.start - left.start)) {
    next = `${next.slice(0, edit.start)}${edit.replacement}${next.slice(edit.end)}`;
    if (next.length > MAX_VERIFIED_WORKSPACE_READ_CONTENT_CHARS) return null;
  }
  return next === currentContent ? null : next;
}

function numberWorkspaceContentLines(content: string): string {
  const ranges = workspaceSourceLineRanges(content);
  return ranges.map((line, index) =>
    `${index + 1}|${content.slice(line.start, line.contentEnd)}`
  ).join("\n");
}

function workspaceSourceLineRanges(content: string): WorkspaceSourceLineRange[] {
  const ranges: WorkspaceSourceLineRange[] = [];
  let start = 0;
  const newline = /\r\n|\r|\n/gu;
  for (let match = newline.exec(content); match; match = newline.exec(content)) {
    ranges.push({
      start,
      contentEnd: match.index,
      separator: match[0],
    });
    start = match.index + match[0].length;
  }
  ranges.push({ start, contentEnd: content.length, separator: "" });
  return ranges;
}

function preferredWorkspaceLineSeparator(
  lines: readonly WorkspaceSourceLineRange[],
): string {
  return lines.find((line) => line.separator)?.separator ?? "";
}

function normalizeWorkspaceReplacementLineEndings(
  value: string,
  separator: string,
): string {
  return value.replace(/\r\n|\r|\n/gu, separator);
}

/**
 * Reject model shorthand before it can replace a hash-bound source file.
 * This deliberately targets only whole-payload stubs; legitimate source may
 * contain TODOs or placeholder identifiers inside an otherwise complete file.
 */
export function isIncompleteWorkspaceReplacementContent(
  value: unknown,
): boolean {
  if (typeof value !== "string") return true;
  const normalized = value
    .trim()
    .replace(/^```[^\r\n]*[\r\n]+|[\r\n]+```$/gu, "")
    .trim()
    .toLowerCase();
  if (!normalized) return true;
  return /^(?:(?:\/\/|#|\/\*+|<!--)\s*)?(?:placeholder|todo|fixme|tbd|tbc|pass|stub|same as (?:above|before)|unchanged|content omitted|implementation omitted|\.\.\.)(?:\s*(?:\*\/|-->)\s*)?[.!;]*$/u.test(
    normalized,
  );
}

/**
 * Omitted-content shorthand cannot authorize a destructive replacement. When
 * the exact graph already has a fresh hash/content read, bind the operation to
 * that byte-identical content so the node records a safe no-op and validation
 * remains responsible for deciding whether another file still needs repair.
 */
export function bindIncompleteWorkspaceReplacementToVerifiedNoop(
  toolCall: ModelToolCall,
  observation: VerifiedWorkspaceReadObservation,
): ModelToolCall {
  return {
    ...toolCall,
    arguments: {
      workspaceId: observation.workspaceId,
      path: observation.path,
      content: observation.content,
      expectedSha256: observation.sha256,
    },
  };
}

function getMissionGraphWorkspaceWriteSelectors(
  graph: MissionGraphV3,
): string[] {
  const selectors = new Set<string>();
  for (const node of Object.values(graph.nodes)) {
    const lifecycle = getSafeMissionCompositeLifecycleSpecV1(node);
    if (lifecycle) {
      for (const action of lifecycle.actions) {
        if (
          isAdaptiveCodeWorkspaceMutationToolNameV1(action.toolName) &&
          action.selector &&
          !action.selector.startsWith("prompt-scoped-")
        ) {
          selectors.add(action.selector);
        }
      }
      continue;
    }
    if (!node.allowedTools.includes("code_workspace_write_expected")) {
      continue;
    }
    const selector = getMissionGraphNodeSelector(node);
    if (selector && !selector.startsWith("prompt-scoped-")) {
      selectors.add(selector);
    }
  }
  return [...selectors].sort();
}

function normalizeValidationRecoveryCandidatePathV1(
  value: unknown,
): string | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim().replace(/^(?:\.\/)+/u, "");
  if (
    !normalized ||
    normalized.length > 512 ||
    normalized.includes("\\") ||
    normalized.startsWith("/") ||
    /^[A-Za-z]:/u.test(normalized) ||
    /[\u0000-\u001f\u007f]/u.test(normalized)
  ) {
    return null;
  }
  const segments = normalized.split("/");
  if (segments.some((segment) => !segment || segment === "." || segment === "..")) {
    return null;
  }
  return normalized;
}

function validationRecoveryPathAtOrBelowV1(
  allowedPath: string,
  candidatePath: string,
): boolean {
  const allowed = allowedPath.toLowerCase();
  const candidate = candidatePath.toLowerCase();
  return candidate === allowed || candidate.startsWith(`${allowed}/`);
}

function isConcreteRepositoryRecoveryPathV1(path: string): boolean {
  const basename = path.split("/").at(-1) ?? path;
  return (
    /\.[A-Za-z0-9][A-Za-z0-9._-]{0,31}$/u.test(basename) ||
    /^(?:Dockerfile|Jenkinsfile|Makefile|README|LICENSE)$/iu.test(basename)
  );
}

/**
 * Repository-bound set-loose missions intentionally let the provider choose
 * issue-required filenames after the independent Linear read. Those paths may
 * therefore be absent from the initial graph, but the canonical workspace
 * creation receipt still carries the exact trusted repository allowlist.
 * Recover only concrete allowlisted files plus verified mutation paths beneath
 * that same single scope; never infer a new descendant of an allowed directory.
 */
function getReceiptBackedWorkspaceRecoveryPathsV1(
  durableReceipts: readonly AgentRunReceipt[],
): string[] {
  const scopeVariants = new Map<string, string[]>();
  for (const receipt of durableReceipts) {
    if (
      receipt.toolName !== "code_workspace_create" ||
      (receipt.commitKind !== "committed" &&
        receipt.commitKind !== "reconciled") ||
      receipt.readback?.status !== "verified" ||
      receipt.resource?.system !== "workspace"
    ) {
      continue;
    }
    const output = isRecord(receipt.output) ? receipt.output : null;
    const scope =
      output && isRecord(output.repositoryWriteScope)
        ? output.repositoryWriteScope
        : null;
    if (!scope || !Array.isArray(scope.projects)) continue;
    const allowedPaths = [
      ...new Set(
        scope.projects.flatMap((rawProject) => {
          if (!isRecord(rawProject) || !Array.isArray(rawProject.allowedPaths)) {
            return [];
          }
          return rawProject.allowedPaths
            .map(normalizeValidationRecoveryCandidatePathV1)
            .filter((path): path is string => path !== null);
        }),
      ),
    ].sort();
    if (allowedPaths.length > 0) {
      scopeVariants.set(JSON.stringify(allowedPaths), allowedPaths);
    }
  }
  if (scopeVariants.size !== 1) return [];
  const allowedPaths = [...scopeVariants.values()][0]!;
  const candidates = new Set(
    allowedPaths.filter(isConcreteRepositoryRecoveryPathV1),
  );
  for (const receipt of durableReceipts) {
    if (
      !isAdaptiveCodeWorkspaceMutationToolNameV1(receipt.toolName) ||
      !receiptProvesWorkspaceContentChangeV1(receipt)
    ) {
      continue;
    }
    const path = normalizeValidationRecoveryCandidatePathV1(
      getCanonicalWorkspaceMutationReceiptPathV1(receipt),
    );
    if (
      path &&
      allowedPaths.some((allowedPath) =>
        validationRecoveryPathAtOrBelowV1(allowedPath, path),
      )
    ) {
      candidates.add(path);
    }
  }
  return [...candidates].sort();
}

/**
 * Treat validator output as untrusted narrowing evidence only. When it names
 * one or more exact writable files, later correction nodes may mutate only
 * those files; every other exact path is converted to a SHA-bound no-op. If
 * the diagnostic names no writable file, this returns an empty set and does
 * not invent a target or suppress a potentially necessary repair.
 */
/** True when the red diagnostic is a parse/indent failure that needs a full rewrite. */
export function diagnosticRequestsFullFileReplacement(
  diagnostic: CodeValidationDiagnosticObservation | null,
  path: string,
): boolean {
  if (!diagnostic || !path.trim()) return false;
  const searchable = `${diagnostic.stdout}\n${diagnostic.stderr}`.replace(
    /\\/gu,
    "/",
  );
  if (!searchable.trim()) return false;
  const normalizedPath = path.replace(/\\/gu, "/").toLowerCase();
  const basename = normalizedPath.split("/").at(-1) ?? normalizedPath;
  const mentionsPath =
    searchable.toLowerCase().includes(normalizedPath) ||
    (basename.length > 0 && searchable.toLowerCase().includes(basename));
  if (!mentionsPath) return false;
  return /(?:SyntaxError|IndentationError|TabError|ParseError|unexpected indent|invalid syntax|unindent does not match)/iu
    .test(searchable);
}

export function getDiagnosticSelectedWorkspaceCorrectionPaths(
  graph: MissionGraphV3,
  diagnostic: CodeValidationDiagnosticObservation | null,
  durableReceipts: readonly AgentRunReceipt[] = [],
): string[] {
  if (!diagnostic) return [];
  const searchable = `${diagnostic.stdout}\n${diagnostic.stderr}`
    .replace(/\\/gu, "/")
    .toLowerCase();
  if (!searchable.trim()) return [];
  const writablePaths = [
    ...new Set([
      ...getMissionGraphWorkspaceWriteSelectors(graph),
      ...getReceiptBackedWorkspaceRecoveryPathsV1(durableReceipts),
    ]),
  ].sort();
  const directMatches = writablePaths.filter((path) => {
    const normalizedPath = path.replace(/\\/gu, "/").toLowerCase();
    if (searchable.includes(normalizedPath)) return true;
    const extensionIndex = normalizedPath.lastIndexOf(".");
    const modulePath = (extensionIndex > normalizedPath.lastIndexOf("/")
      ? normalizedPath.slice(0, extensionIndex)
      : normalizedPath
    ).replace(/\//gu, ".");
    return modulePath.includes(".") && searchable.includes(modulePath);
  });
  const assertionLike =
    /(?:assertionerror|\bassert\b|mismatch|expected|actual|test(?:s)? failed|validation failed)/iu
      .test(searchable);
  const protectedContractFailure =
    /(?:^|[/\s])scripts\/verify_[a-z0-9_]+\.py\b|protected\s+contract/iu.test(
      searchable,
    );
  const implementationCandidates = writablePaths.filter(
    isPlausibleWorkspaceImplementationPath,
  );
  if (directMatches.length > 0) {
    if (!assertionLike) return directMatches;

    // Assertion tracebacks normally name the generated test/verifier line
    // that observed the defect. Prefer a directly named implementation module
    // so agents cannot weaken tests when the implementation is clearly named.
    const directImplementationMatches = directMatches.filter(
      isPlausibleWorkspaceImplementationPath,
    );
    if (directImplementationMatches.length > 0) {
      return directImplementationMatches;
    }
    const directTestMatches = directMatches.filter(isPlausibleWorkspaceTestPath);
    // When only self-authored tests appear and the protected scripts/contract
    // did not fail, the protected contract already accepted the implementation.
    // Allow correcting those tests instead of forcing preserveCurrent on them
    // while rewriting a green game module.
    if (directTestMatches.length > 0 && !protectedContractFailure) {
      return directTestMatches;
    }
    return implementationCandidates.length === 1
      ? implementationCandidates
      : [];
  }

  // A protected assertion often reports only its own immutable verifier path
  // (for example scripts/verify_project.py), not the generated module whose
  // behavior was wrong. Narrow only when the declared outputs contain exactly
  // one plausible implementation module. This can reduce authority but never
  // chooses between multiple source candidates.
  if (!assertionLike) {
    return [];
  }
  return implementationCandidates.length === 1
    ? implementationCandidates
    : [];
}

function isPlausibleWorkspaceTestPath(path: string): boolean {
  const normalized = path.replace(/\\/gu, "/").toLowerCase();
  const basename = normalized.split("/").at(-1) ?? normalized;
  if (/(?:^|\/)(?:test|tests|spec|specs|__tests__)(?:\/|$)/u.test(normalized)) {
    return true;
  }
  return /(?:^|[._-])(?:test|spec)\.[a-z0-9]+$/u.test(basename);
}

function isPlausibleWorkspaceImplementationPath(path: string): boolean {
  const normalized = path.replace(/\\/gu, "/").toLowerCase();
  const basename = normalized.split("/").at(-1) ?? normalized;
  if (/\.(?:md|mdx|rst|txt|adoc)$/u.test(basename)) return false;
  if (isPlausibleWorkspaceTestPath(normalized)) {
    return false;
  }
  if (/^(?:__init__|index|main|cli)\.[a-z0-9]+$/u.test(basename)) {
    return false;
  }
  return /\.(?:py|ts|tsx|js|jsx|mjs|cjs|java|c|cc|cpp|cxx|h|hh|hpp|hxx|cs|go|rs|rb|php|swift|kt|kts)$/u.test(
    basename,
  );
}

function forgetVerifiedWorkspaceReadObservation(
  runtimeCache: AgentRuntimeCache | undefined,
  workspaceId: string | undefined,
  path: string | undefined,
): void {
  if (!runtimeCache?.verifiedWorkspaceReads || !path) return;
  if (workspaceId) {
    runtimeCache.verifiedWorkspaceReads.delete(
      verifiedWorkspaceReadKey(
        normalizeWorkspaceObservationId(workspaceId),
        path,
      ),
    );
    return;
  }
  for (const [key, observation] of runtimeCache.verifiedWorkspaceReads) {
    if (observation.path === path) {
      runtimeCache.verifiedWorkspaceReads.delete(key);
    }
  }
}

function rememberTrustedWebFetchResult(
  runtimeCache: AgentRuntimeCache | undefined,
  toolName: string,
  result: ToolExecutionResult,
): void {
  if (toolName !== "web_fetch" || !result.ok || !runtimeCache) return;
  const output = isRecord(result.output) ? result.output : null;
  if (!output) return;
  const reference =
    typeof output.normalizedUrl === "string"
      ? output.normalizedUrl.trim()
      : typeof output.url === "string"
        ? output.url.trim()
        : "";
  const contentHash =
    typeof output.contentHash === "string"
      ? output.contentHash.trim().toLowerCase()
      : "";
  if (!reference || !/^sha256:[a-f0-9]{64}$/u.test(contentHash)) return;
  runtimeCache.trustedWebFetchResults ??= new Map();
  runtimeCache.trustedWebFetchResults.set(
    `${reference}:${contentHash}`,
    result,
  );
}

export function restoreTrustedWebFetchResultsFromEvidence(
  runtimeCache: AgentRuntimeCache,
  evidence: readonly MissionEvidence[],
): void {
  runtimeCache.trustedWebFetchResults ??= new Map();
  for (const item of evidence) {
    if (
      item.kind !== "web_source" ||
      item.usableSource !== true ||
      !item.url ||
      !item.contentHash ||
      !/^sha256:[a-f0-9]{64}$/u.test(item.contentHash)
    ) {
      continue;
    }
    runtimeCache.trustedWebFetchResults.set(
      `${item.url}:${item.contentHash}`,
      {
        ok: true,
        toolName: "web_fetch",
        output: {
          url: item.url,
          normalizedUrl: item.url,
          title: item.title,
          content: item.summary,
          contentHash: item.contentHash,
          parserStatus: item.parserStatus ?? "parsed",
        },
      },
    );
  }
}

interface ToolApprovalRequestInfo {
  action: string;
  reason: string;
  policyTags: string[];
  timeoutMs?: number;
}

function getToolApprovalRequestInfo(
  toolCall: ModelToolCall,
  result: ToolExecutionResult,
): ToolApprovalRequestInfo | null {
  if (!result.ok || !isRecord(result.output)) {
    return null;
  }

  if (result.output.status !== "requires_approval") {
    return null;
  }

  const approval = isRecord(result.output.approval)
    ? result.output.approval
    : undefined;
  const safetyDecision = isRecord(result.output.safetyDecision)
    ? result.output.safetyDecision
    : undefined;
  const action = getString(approval?.action) ?? getString(result.output.operation) ?? toolCall.name;
  const reason =
    getString(approval?.reason) ??
    getString(result.output.reason) ??
    getString(safetyDecision?.reason) ??
    `${toolCall.name} requires approval.`;
  const tags = [
    ...getStringArray(safetyDecision?.policyTags),
    ...getStringArray(approval?.policyTags),
  ];
  const timeoutMs =
    getNumber(approval?.expiresInMs) ?? getNumber(result.output.expiresInMs);

  return {
    action,
    reason,
    policyTags: tags.length ? tags : ["approval_required"],
    timeoutMs,
  };
}

function compareRouterWithRegex(
  routed: RoutedMissionIntent,
  regexIntent: MissionIntent,
): "agree" | "disagree" {
  const routerWrite = routed.writeScope !== "none";
  const regexWrite = regexIntent.noteOutput || regexIntent.explicitMutation;
  const routerRead = routed.needsVaultContext || routed.mode === "vault_read";
  const regexRead = regexIntent.vaultContext;
  const routerWeb =
    routed.needsWebEvidence ||
    routed.mode === "web_research" ||
    routed.mode === "deep_research";
  const regexWeb = regexIntent.autonomyScope.read.web;
  const routerCode = routed.needsCodeExecution || routed.mode === "code_workflow";
  const regexCode = regexIntent.autonomyScope.write.artifacts;

  return routerWrite === regexWrite &&
    routerRead === regexRead &&
    routerWeb === regexWeb &&
    routerCode === regexCode
    ? "agree"
    : "disagree";
}

function buildToolCallFallbackId(
  runId: string,
  step: number,
  toolIndex: number | string,
  toolName: string,
): string {
  return `call_${runId}_${step}_${toolIndex}_${toolName}`.replace(
    /[^A-Za-z0-9_-]/g,
    "_",
  );
}

function formatObservedToolFailureStatus(
  toolName: string,
  result: ToolExecutionResult,
): string {
  const detail = result.error?.message?.trim();
  if (result.error?.code === "policy_blocked") {
    if (detail?.startsWith("What: ")) {
      return detail;
    }
    const phaseMatch = /during research (\w+) phase/i.exec(detail ?? "");
    if (phaseMatch || /research_phase_gate|phase gate/i.test(detail ?? "")) {
      return formatFailureCopy(
        phaseGateFailureCopy(phaseMatch?.[1], detail),
      );
    }
    return formatFailureCopy(policyBlockFailureCopy(toolName, detail));
  }
  if (
    result.error?.code?.startsWith("approval_") ||
    /approval (denied|expired|aborted)/i.test(detail ?? "")
  ) {
    const decision =
      result.error?.code?.replace(/^approval_/, "") ||
      /approval (denied|expired|aborted)/i.exec(detail ?? "")?.[1] ||
      "denied";
    return formatFailureCopy(approvalDeniedFailureCopy(toolName, decision));
  }
  if (toolName === "web_fetch" || toolName === "web_search") {
    return formatWebFetchToolFailureCopy(detail);
  }
  return detail?.startsWith("What: ")
    ? detail
    : `Tool returned error: ${toolName}${detail ? ` (${detail})` : ""}`;
}

function getToolCacheKey(name: string, args: Record<string, unknown>): string {
  return `${name}:${stableStringify(args)}`;
}

async function reconcileHistoricalCanvasPreflightOperations({
  records,
  toolContext,
  now,
}: {
  records: readonly OperationJournalRecord[];
  toolContext: ToolExecutionContext;
  now: Date;
}): Promise<{
  records: OperationJournalRecord[];
  notAppliedCount: number;
  adoptedCount: number;
  conflictingCount: number;
}> {
  let notAppliedCount = 0;
  let adoptedCount = 0;
  let conflictingCount = 0;
  const vault = toolContext.app.vault as unknown as {
    getAbstractFileByPath?: (path: string) => unknown;
    getFileByPath?: (path: string) => unknown;
    cachedRead?: (file: unknown) => Promise<string>;
    read?: (file: unknown) => Promise<string>;
  };

  const reconciled: OperationJournalRecord[] = [];
  for (const record of records) {
    if (!isHistoricalCanvasPreflightRejection(record) || !record.targetPath) {
      reconciled.push({ ...record });
      continue;
    }

    let targetPath: string;
    try {
      targetPath = normalizeVaultPath(record.targetPath);
    } catch {
      conflictingCount += 1;
      reconciled.push({ ...record });
      continue;
    }
    const file =
      vault.getAbstractFileByPath?.(targetPath) ??
      vault.getFileByPath?.(targetPath) ??
      null;
    if (!file) {
      const recovered = reconcileHistoricalCanvasPreflightJournalRecord(
        record,
        { status: "absent" },
        now,
      );
      if (recovered.state === "failed") notAppliedCount += 1;
      reconciled.push(recovered);
      continue;
    }

    if (!record.expectedPostWriteHash) {
      conflictingCount += 1;
      reconciled.push(
        reconcileHistoricalCanvasPreflightJournalRecord(record, {
          status: "unverifiable",
        }),
      );
      continue;
    }

    const read = vault.cachedRead ?? vault.read;
    if (!read) {
      conflictingCount += 1;
      reconciled.push(
        reconcileHistoricalCanvasPreflightJournalRecord(record, {
          status: "unverifiable",
        }),
      );
      continue;
    }
    try {
      const content = await read.call(vault, file);
      const observedFingerprint = await sha256MissionFingerprint(content);
      const matches =
        observedFingerprint === record.expectedPostWriteHash;
      const recovered = reconcileHistoricalCanvasPreflightJournalRecord(
        record,
        matches
          ? { status: "fingerprint_match", observedFingerprint }
          : { status: "conflicting", observedFingerprint },
        now,
      );
      if (recovered.state === "committed") {
        adoptedCount += 1;
      } else {
        conflictingCount += 1;
      }
      reconciled.push(recovered);
    } catch {
      conflictingCount += 1;
      reconciled.push(
        reconcileHistoricalCanvasPreflightJournalRecord(record, {
          status: "unverifiable",
        }),
      );
    }
  }
  return {
    records: reconciled,
    notAppliedCount,
    adoptedCount,
    conflictingCount,
  };
}

function stableStringify(value: unknown): string {
  return JSON.stringify(stableNormalize(value));
}

function hashOperationInput(value: unknown): string {
  const input = stableStringify(value);
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return `fnv1a32:${hash.toString(16).padStart(8, "0")}`;
}

function stableNormalize(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => stableNormalize(item));
  }

  if (!isRecord(value)) {
    return value;
  }

  return Object.keys(value)
    .sort()
    .reduce<Record<string, unknown>>((output, key) => {
      output[key] = stableNormalize(value[key]);
      return output;
    }, {});
}

function runtimeReceiptToAgentRunReceipt(
  receipt: MissionRuntimeReceipt,
): AgentRunReceipt | null {
  if (!isAgentRunReceiptOperation(receipt.operation)) {
    return null;
  }
  return {
    version: receipt.version,
    id: receipt.id,
    runId: receipt.runId,
    toolName: receipt.toolName,
    operation: receipt.operation,
    message: receipt.message,
    actionId: receipt.actionId,
    resource: receipt.resource ? { ...receipt.resource } : undefined,
    relatedResources: receipt.relatedResources?.map((resource) => ({
      ...resource,
    })),
    payloadFingerprint: receipt.payloadFingerprint,
    grantId: receipt.grantId,
    idempotencyKey: receipt.idempotencyKey,
    providerRequestId: receipt.providerRequestId,
    startedAt: receipt.startedAt,
    committedAt: receipt.committedAt,
    commitKind: receipt.commitKind,
    readback: receipt.readback ? { ...receipt.readback } : undefined,
    effects: receipt.effects
      ? {
          ...receipt.effects,
          changedFields: receipt.effects.changedFields
            ? [...receipt.effects.changedFields]
            : undefined,
        }
      : undefined,
    path: receipt.path,
    toPath: receipt.toPath,
    backupPath: receipt.backupPath,
    restoredFromBackupPath: receipt.restoredFromBackupPath,
    bytesWritten: receipt.bytesWritten,
    bytesDeleted: receipt.bytesDeleted,
    affectedCount: receipt.affectedCount,
    output: receipt.output,
  };
}

function missionLedgerStatusToRuntimeStatus(
  status: MissionLedgerStatus,
): MissionRuntimeStatus {
  switch (status) {
    case "complete":
      return "complete";
    case "blocked":
      return "blocked";
    case "stopped":
      return "stopped";
    case "budget":
      return "paused";
    case "running":
    default:
      return "running";
  }
}

function normalizeRuntimeAcceptance(
  acceptance: MissionLedger["acceptance"],
): MissionAcceptanceResult | undefined {
  if (
    !acceptance ||
    (acceptance.status !== "pass" &&
      acceptance.status !== "fail" &&
      acceptance.status !== "needs_more_work")
  ) {
    return undefined;
  }
  return {
    status: acceptance.status,
    confidence: acceptance.confidence,
    missing: [...acceptance.missing],
    reasons: [...acceptance.reasons],
    nextAction: acceptance.nextAction,
  };
}

function isAgentRunReceiptOperation(
  operation: string,
): operation is AgentRunReceipt["operation"] {
  return (
    operation === "create" ||
    operation === "create_folder" ||
    operation === "append" ||
    operation === "replace" ||
    operation === "edit" ||
    operation === "highlight" ||
    operation === "restore" ||
    operation === "retitle" ||
    operation === "rename_current_file" ||
    operation === "link_related_notes" ||
    operation === "move" ||
    operation === "trash" ||
    operation === "delete"
    || operation === "read"
    || operation === "list"
    || operation === "search"
    || operation === "update"
    || operation === "archive"
    || operation === "unarchive"
    || operation === "unlink"
    || operation === "validate"
    || operation === "promote"
    || operation === "merge"
    || operation === "execute"
    || operation === "install"
    || operation === "commit"
    || operation === "integrate"
    || operation === "publish"
    || operation === "link"
  );
}

function nowMs(): number {
  return typeof performance !== "undefined" ? performance.now() : Date.now();
}

function elapsedMs(startedAt: number): number {
  return Math.max(0, Math.round(nowMs() - startedAt));
}

function extractTokenUsageFields(raw: unknown): Partial<AgentRunMetricEvent> {
  const usage = extractProviderTokenUsage(raw);
  return usage.reported
    ? {
        promptTokens: usage.promptTokens,
        completionTokens: usage.completionTokens,
        totalTokens: usage.totalTokens,
      }
    : {};
}

function isPureVaultCitationScope(
  researchPlan: ResearchPlan | null | undefined,
): boolean {
  return Boolean(
    researchPlan?.mode === "deep_vault" &&
      researchPlan.sourceRequirements.minFetchedSources === 0,
  );
}

function hasClosedPassageCitationScope(
  researchPlan: ResearchPlan | null | undefined,
  acceptedPassageIds: string[],
): boolean {
  return researchPlan !== null && researchPlan !== undefined
    ? true
    : acceptedPassageIds.length > 0;
}

function getCorrectionPassageIds(
  acceptedPassageIds: string[],
  researchPlan: ResearchPlan | null | undefined,
  claimLedger: ClaimLedger | null,
): string[] {
  return hasClosedPassageCitationScope(researchPlan, acceptedPassageIds)
    ? acceptedPassageIds
    : claimLedger?.knownPassageIds ?? [];
}

function getAcceptedMissionPassageIds(
  evidence: MissionEvidence[],
  researchPlan?: ResearchPlan | null,
): string[] {
  const pureVaultScope = isPureVaultCitationScope(researchPlan);
  return [
    ...new Set(
      evidence
        .filter(
          (item) =>
            pureVaultScope
              ? item.kind === "vault_note"
              : isFetchedWebEvidence(item),
        )
        .flatMap((item) => [
          ...(item.passageId ? [item.passageId] : []),
          ...(item.passageIds ?? []),
        ])
        .filter((item) =>
          /^source:[a-z0-9-]+:passage:\d+-\d+$/u.test(item),
        ),
    ),
  ].slice(0, 16);
}

export function attachGroundedPassageCitations(
  draft: string,
  ledger: ClaimLedger,
  allowedPassageIds: string[] = ledger.knownPassageIds,
): { content: string; insertedPassageIds: string[] } {
  const ledgerKnown = new Set(ledger.knownPassageIds);
  const known = new Set(
    allowedPassageIds.filter((passageId) => ledgerKnown.has(passageId)),
  );
  const replacements: Array<{
    start: number;
    end: number;
    text: string;
    passageIds: string[];
  }> = [];

  for (const claim of ledger.claims) {
    if (claim.status !== "grounded" || !claim.text.trim()) continue;
    const passageIds = [
      ...new Set(
        claim.passageIds.filter(
          (passageId) =>
            known.has(passageId) && !claim.text.includes(passageId),
        ),
      ),
    ];
    if (passageIds.length === 0) continue;
    const start = draft.indexOf(claim.text);
    if (start < 0 || draft.indexOf(claim.text, start + claim.text.length) >= 0) {
      continue;
    }

    const citation = passageIds.map((passageId) => `[${passageId}]`).join(" ");
    const punctuated = /[.!?]$/u.test(claim.text)
      ? `${claim.text.slice(0, -1)} ${citation}${claim.text.slice(-1)}`
      : `${claim.text} ${citation}`;
    replacements.push({
      start,
      end: start + claim.text.length,
      text: punctuated,
      passageIds,
    });
  }

  const insertedPassageIds = [
    ...new Set(replacements.flatMap((replacement) => replacement.passageIds)),
  ];
  let content = draft;
  for (const replacement of replacements.sort((left, right) => right.start - left.start)) {
    content =
      content.slice(0, replacement.start) +
      replacement.text +
      content.slice(replacement.end);
  }
  return {
    content,
    insertedPassageIds,
  };
}

const PASSAGE_CITATION_TOKEN_PATTERN =
  /\[\s*(source:[a-z0-9-]+:passage:\d+-\d+)\s*\]|(source:[a-z0-9-]+:passage:\d+-\d+)/giu;
const REMOVED_PASSAGE_CITATION_SENTINEL = "\u{e000}";

/**
 * Narrows model-authored internal passage citations to the host-selected set.
 *
 * A research run can know both fetched web passages and vault-context passages,
 * but a web-source writeback contract must not silently widen to the latter.
 * Removing an out-of-scope marker is not sufficient proof by itself: callers
 * must re-run acceptance on the returned content before any mutation.
 */
export function constrainPassageCitationScope(
  draft: string,
  allowedPassageIds: string[],
): { content: string; removedPassageIds: string[] } {
  const allowed = new Set(allowedPassageIds);
  const removedPassageIds: string[] = [];
  let content = draft.replace(
    PASSAGE_CITATION_TOKEN_PATTERN,
    (match, bracketedId: string | undefined, bareId: string | undefined) => {
      const passageId = bracketedId ?? bareId ?? "";
      if (allowed.has(passageId)) {
        return match;
      }
      if (passageId && !removedPassageIds.includes(passageId)) {
        removedPassageIds.push(passageId);
      }
      return REMOVED_PASSAGE_CITATION_SENTINEL;
    },
  );

  if (removedPassageIds.length > 0) {
    const sentinel = REMOVED_PASSAGE_CITATION_SENTINEL;
    content = content
      .replace(
        new RegExp(`(^|\\r?\\n)[ \\t]*(?:${sentinel}[ \\t]*)+`, "gu"),
        "$1",
      )
      .replace(
        new RegExp(
          `[ \\t]*(?:${sentinel}[ \\t]*)+(?=[,.;:!?\\)\\]\\r\\n]|$)`,
          "gu",
        ),
        "",
      )
      .replace(new RegExp(`[ \\t]*(?:${sentinel}[ \\t]*)+`, "gu"), " ");
  }

  return { content, removedPassageIds };
}

function buildPassageGroundedWritebackContract(passageIds: string[]): string {
  return [
    "Passage-grounded writeback contract:",
    `Accepted passage identifiers: ${passageIds.join(", ")}.`,
    "Return only the requested note markdown or one current-note write call.",
    "Put an accepted identifier on every supported material-claim sentence, not only in a Sources footer.",
    passageIds.length > 1
      ? "Use every listed fetched-source identifier at least once."
      : "Use the listed identifier exactly as written.",
    "Reuse fetched-passage terms. Do not invent identifiers, URLs, facts, or quotations.",
  ].join("\n");
}

function measureSerializedChars(value: unknown): number {
  try {
    return JSON.stringify(value)?.length ?? 0;
  } catch {
    return 0;
  }
}

/**
 * Dedicated utility-model assist for research subquestions. Returns null when
 * no utility model is configured so createResearchPlanWithAssist stays deterministic.
 */
/**
 * Optional utility-model call that lets the model decide whether a prompt
 * warrants grounded research at all — activating it semantically for prompts
 * that clearly need sources but name no research keywords. The deterministic
 * keyword classifier remains the floor; this only fills its silence. Returns
 * undefined when no dedicated utility model is configured.
 */
function buildResearchModeAssist(
  modelClient: ModelClient,
  utilityModel: string | undefined,
): ResearchModeAssist | undefined {
  const model = utilityModel?.trim();
  if (!model) {
    return undefined;
  }
  return async (request) => {
    const response = await modelClient.chat({
      model,
      messages: [
        {
          role: "system",
          content:
            'Decide whether answering this request well requires grounding in real sources (facts, history, current events, data, comparisons, anything a careful writer would cite) versus pure composition or opinion. Return only a JSON object like {"mode":"deep_web","sourceFloor":3,"rationale":"one short sentence"}. mode: deep_web = needs public web sources; deep_vault = should draw on the user\'s own notes/vault; deep_hybrid = both; none = no grounding needed. sourceFloor: how many distinct sources the topic warrants, 1-8. No markdown, no extra text.',
        },
        {
          role: "user",
          content: request.prompt,
        },
      ],
      think: false,
    });
    const raw = response.message.content.trim();
    const start = raw.indexOf("{");
    const end = raw.lastIndexOf("}");
    if (start < 0 || end <= start) {
      return null;
    }
    try {
      return (JSON.parse(raw.slice(start, end + 1)) ??
        null) as ResearchModeAssessment | null;
    } catch {
      return null;
    }
  };
}

/**
 * Optional utility-model call that lets the model — not just a keyword
 * classifier — set the starting research depth. Never uses the main mission
 * model; returns undefined when no dedicated utility model is configured, in
 * which case the deterministic classifier decides the tier.
 */
function buildResearchEffortAssist(
  modelClient: ModelClient,
  utilityModel: string | undefined,
): ResearchEffortAssist | undefined {
  const model = utilityModel?.trim();
  if (!model) {
    return undefined;
  }
  return async (request) => {
    const response = await modelClient.chat({
      model,
      messages: [
        {
          role: "system",
          content:
            'Judge how much research effort a mission truly deserves. Return only a JSON object like {"tier":"quick","risk":"low","freshness":"helpful","rationale":"one short sentence"}. tier: quick = a single quick lookup; standard = a few sources; deep = multi-source comparison or verification; extended = exhaustive or overnight work. risk: low|medium|high|critical. freshness: none|helpful|required. No markdown, no extra text.',
        },
        {
          role: "user",
          content: [`Mode: ${request.mode}`, `Mission: ${request.prompt}`].join(
            "\n",
          ),
        },
      ],
      think: false,
    });
    const raw = response.message.content.trim();
    const start = raw.indexOf("{");
    const end = raw.lastIndexOf("}");
    if (start < 0 || end <= start) {
      return null;
    }
    try {
      return (JSON.parse(raw.slice(start, end + 1)) ??
        null) as ResearchEffortAssessment | null;
    } catch {
      return null;
    }
  };
}

function buildResearchSubquestionAssist(
  modelClient: ModelClient,
  utilityModel: string | undefined,
):
  | ((request: {
      prompt: string;
      mode: import("./agent/researchPlan").ResearchMode;
      seedQuestions: string[];
    }) => Promise<string[] | null>)
  | undefined {
  const model = utilityModel?.trim();
  if (!model) {
    return undefined;
  }
  return async (request) => {
    const response = await modelClient.chat({
      model,
      messages: [
        {
          role: "system",
          content:
            "Return only a JSON array of 2-6 short research subquestions as strings. No markdown.",
        },
        {
          role: "user",
          content: [
            `Mode: ${request.mode}`,
            `Mission: ${request.prompt}`,
            `Seed questions: ${JSON.stringify(request.seedQuestions)}`,
          ].join("\n"),
        },
      ],
      think: false,
    });
    const raw = response.message.content.trim();
    const start = raw.indexOf("[");
    const end = raw.lastIndexOf("]");
    if (start < 0 || end <= start) {
      return null;
    }
    try {
      const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
      if (!Array.isArray(parsed)) {
        return null;
      }
      return parsed
        .filter((item): item is string => typeof item === "string")
        .map((item) => item.replace(/\s+/g, " ").trim())
        .filter((item) => item.length >= 8)
        .slice(0, 8);
    } catch {
      return null;
    }
  };
}
